'use client';

import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useEffect, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { ArrowRight, ChevronLeft, ChevronRight, MessageCircle, ShieldCheck, Sparkles, Truck } from 'lucide-react';
import ProductCard from '@/components/ProductCard';
import CategoryTile from '@/components/CategoryTile';
import Spinner from '@/components/common/Spinner';
import api from '@/services/api';

interface Product {
	id: string;
	name: string;
	subtitle?: string | null;
	description?: string;
	price: number;
	imageUrl?: string | null;
	stock?: number | null;
	tags?: string[];
}

interface ApiProduct {
	id: number;
	name: string;
	subtitle?: string | null;
	description?: string | null;
	priceCents: number;
	imageUrl?: string | null;
	stock?: number | null;
	tags?: string[];
}

interface Category {
	slug: string;
	name: string;
	description?: string;
}

interface ApiCategory {
	id: number;
	name: string;
	slug: string;
	orderIndex: number;
}


export default function HomeClient() {
	const router = useRouter();
	const heroSlides = [
		{
			kicker: 'Nutopiano Shop',
			title: 'Yeni sezon ürünleri keşfet',
			description: 'Seçilmiş ürünler, hızlı teslimat ve güvenli ödeme ile alışverişini tamamla.',
			ctaLabel: 'Shop now',
			ctaHref: '/products',
			imageUrl: '/hero/IMG_3958.JPG',
		},
		{
			kicker: 'Koleksiyonlar',
			title: 'Kategoriler arasında gez',
			description: 'İhtiyacın olan ürünleri koleksiyonlara göre hızlıca bul.',
			ctaLabel: 'Koleksiyonlara git',
			ctaHref: '/categories',
			imageUrl: '/hero/IMG_3959.JPG',
		},
		{
			kicker: 'Hızlı & güvenli',
			title: 'Sepete ekle, hemen tamamla',
			description: 'Modern kart yapısı ve hover aksiyonlarıyla daha hızlı alışveriş.',
			ctaLabel: 'Öne çıkanları gör',
			ctaHref: '/products',
			imageUrl: '/hero/IMG_3962.JPG',
		},
	] as const;

	const [heroIndex, setHeroIndex] = useState(0);
	const [featuredStartIndex, setFeaturedStartIndex] = useState(0);
	const [featuredPerView, setFeaturedPerView] = useState(4);

	useEffect(() => {
		const interval = window.setInterval(() => {
			setHeroIndex((prev) => (prev + 1) % heroSlides.length);
		}, 6000);
		return () => window.clearInterval(interval);
	}, [heroSlides.length]);

	useEffect(() => {
		const update = () => {
			const width = window.innerWidth;
			if (width < 640) {
				setFeaturedPerView(2);
			} else if (width < 768) {
				setFeaturedPerView(2);
			} else if (width < 1024) {
				setFeaturedPerView(3);
			} else {
				setFeaturedPerView(4);
			}
		};
		update();
		window.addEventListener('resize', update);
		return () => window.removeEventListener('resize', update);
	}, []);

	const activeHero = heroSlides[heroIndex];

	const {
		data: products,
		isLoading: productsLoading,
		isError: productsError,
	} = useQuery<Product[]>({
		queryKey: ['products', { featured: true }],
		queryFn: async () => {
			const res = await api.get<{ data: ApiProduct[] }>('/marketplace/search', {
				params: { page: 1, pageSize: 12, sort: 'newest' },
			});
			return res.data.data.map((p) => ({
				id: String(p.id),
				name: p.name,
				subtitle: p.subtitle ?? null,
				description: p.description ?? undefined,
				price: (p.priceCents ?? 0) / 100,
				imageUrl: p.imageUrl ?? null,
				stock: p.stock ?? null,
				tags: p.tags ?? [],
			}));
		},
	});

	const {
		data: categories,
		isLoading: categoriesLoading,
		isError: categoriesError,
	} = useQuery<Category[]>({
		queryKey: ['public-categories'],
		queryFn: async () => {
			const res = await api.get<ApiCategory[]>('/public/categories');
			return res.data
				.slice()
				.sort((a, b) => a.orderIndex - b.orderIndex)
				.map((c) => ({
					slug: c.slug,
					name: c.name,
				}));
		},
	});

	const isLoading = productsLoading || categoriesLoading;
	const hasError = productsError || categoriesError;

	const featuredCount = products?.length ?? 0;
	const safeFeaturedStartIndex = featuredCount
		? featuredStartIndex % featuredCount
		: 0;

	return (
		<div className="mx-auto flex max-w-6xl flex-col gap-7 px-4 py-10 md:px-6 md:py-12">
			<section className="relative">
				<div
					className="relative overflow-hidden rounded-[var(--radius-3xl)] bg-[var(--neutral-50)]"
					style={{
						backgroundImage: `url('${activeHero.imageUrl}')`,
						backgroundSize: 'cover',
						backgroundPosition: 'center',
					}}
				>
					<div className="absolute inset-0 bg-black/25" />
					<div className="absolute inset-0 z-[5] grid grid-cols-3">
						<button
							type="button"
							aria-label="Önceki slide"
							onPointerUp={(e) => {
								e.preventDefault();
								setHeroIndex((prev) => (prev - 1 + heroSlides.length) % heroSlides.length);
							}}
							onClick={(e) => {
								e.preventDefault();
								setHeroIndex((prev) => (prev - 1 + heroSlides.length) % heroSlides.length);
							}}
							className="h-full w-full bg-transparent"
						/>
						<button
							type="button"
							aria-label="Sayfaya git"
							onPointerUp={(e) => {
								e.preventDefault();
								router.push(activeHero.ctaHref);
							}}
							onClick={(e) => {
								e.preventDefault();
								router.push(activeHero.ctaHref);
							}}
							className="h-full w-full bg-transparent"
						/>
						<button
							type="button"
							aria-label="Sonraki slide"
							onPointerUp={(e) => {
								e.preventDefault();
								setHeroIndex((prev) => (prev + 1) % heroSlides.length);
							}}
							onClick={(e) => {
								e.preventDefault();
								setHeroIndex((prev) => (prev + 1) % heroSlides.length);
							}}
							className="h-full w-full bg-transparent"
						/>
					</div>
					<div className="relative mx-auto flex h-[220px] max-w-6xl flex-col justify-end px-4 pb-12 pt-8 md:h-auto md:min-h-[220px] md:px-6 md:pb-14">
						<button
							type="button"
							onClick={() =>
								setHeroIndex((prev) => (prev - 1 + heroSlides.length) % heroSlides.length)
							}
							className="absolute left-4 top-1/2 z-10 inline-flex h-12 w-12 -translate-y-1/2 items-center justify-center text-white/90 transition hover:text-white"
							aria-label="Önceki"
						>
							<ChevronLeft className="h-8 w-8" />
						</button>
						<button
							type="button"
							onClick={() => setHeroIndex((prev) => (prev + 1) % heroSlides.length)}
							className="absolute right-4 top-1/2 z-10 inline-flex h-12 w-12 -translate-y-1/2 items-center justify-center text-white/90 transition hover:text-white"
							aria-label="Sonraki"
						>
							<ChevronRight className="h-8 w-8" />
						</button>
						<div className="space-y-3 pl-12 pr-20 md:pl-14 md:pr-28">
							<h1 className="max-h-[2.2em] overflow-hidden text-3xl font-serif leading-[1.05] text-white md:max-h-none md:text-6xl">
								{activeHero.title}
							</h1>
							<p className="max-h-[2.8em] max-w-2xl overflow-hidden text-xs leading-snug text-white/80 md:max-h-none md:text-lg md:leading-normal">
								{activeHero.description}
							</p>
						</div>
					</div>
					<div className="absolute bottom-4 left-1/2 z-10 flex -translate-x-1/2 items-center gap-2">
						{heroSlides.map((_, index) => {
							const active = index === heroIndex;
							return (
								<button
									type="button"
									key={`hero-dot-${index}`}
									onClick={() => setHeroIndex(index)}
									className={`h-2.5 w-2.5 rounded-full transition-colors ${
										active ? 'bg-white' : 'bg-white/35 hover:bg-white/60'
									}`}
									aria-label={`Hero slide ${index + 1}`}
								/>
							);
						})}
					</div>
				</div>
				<div className="mx-auto max-w-6xl px-4 pb-2 pt-4 md:px-6 md:pb-4">
					<div className="grid grid-cols-3 gap-3 md:gap-4">
						<div className="flex items-start gap-3">
							<Truck className="mt-0.5 h-5 w-5 text-[var(--accent-600)]" />
							<p className="text-[11px] leading-snug text-[var(--neutral-700)] md:text-sm">
								<span className="font-semibold text-[var(--primary-800)]">Hızlı teslimat</span>
								<br />
								Takipli kargo.
							</p>
						</div>
						<div className="flex items-start gap-3">
							<ShieldCheck className="mt-0.5 h-5 w-5 text-[var(--accent-600)]" />
							<p className="text-[11px] leading-snug text-[var(--neutral-700)] md:text-sm">
								<span className="font-semibold text-[var(--primary-800)]">Güvenli ödeme</span>
								<br />
								Şeffaf adımlar.
							</p>
						</div>
						<div className="flex items-start gap-3">
							<MessageCircle className="mt-0.5 h-5 w-5 text-[var(--accent-600)]" />
							<p className="text-[11px] leading-snug text-[var(--neutral-700)] md:text-sm">
								<span className="font-semibold text-[var(--primary-800)]">WhatsApp</span>
								<br />
								Hızlı dönüş.
							</p>
						</div>
					</div>
				</div>
			</section>

			{isLoading && (
				<section>
					<Spinner fullscreen />
				</section>
			)}

			{hasError && !isLoading && (
				<section className="rounded-lg border border-[var(--error-100)] bg-[var(--error-100)]/10 px-4 py-3 text-sm text-[var(--error-600)]">
					İçerik yüklenirken bir hata oluştu. Lütfen daha sonra tekrar
					deneyin.
				</section>
			)}

			{!isLoading && !hasError && (
				<>
					<section className="space-y-0">
						<div className="flex flex-wrap items-center justify-between gap-4">
							<div>
								<h2
									data-testid="featured-heading"
									className="!text-xs !font-semibold !uppercase !tracking-[0.12em] !leading-none !text-[var(--primary-800)]"
								>
									Öne çıkan ürünler
								</h2>
							</div>
							<Link
								href="/categories"
								className="inline-flex items-center gap-2 !text-xs !font-semibold !uppercase !tracking-[0.12em] !leading-none !text-[var(--primary-800)] transition-colors hover:text-[var(--primary-800)]"
							>
								Tümünü gör <ArrowRight className="h-4 w-4" />
							</Link>
						</div>
						{products && products.length > 0 ? (
							<div className="relative">
								<button
									type="button"
									onClick={() =>
										setFeaturedStartIndex((prev) =>
											featuredCount
													? (prev - 1 + featuredCount) % featuredCount
													: 0,
										)
									}
									className="absolute left-3 top-1/2 z-30 inline-flex h-12 w-12 -translate-y-1/2 items-center justify-center text-white/90 drop-shadow transition hover:text-white"
									aria-label="Önceki"
								>
									<ChevronLeft className="h-9 w-9" />
								</button>
								<button
									type="button"
									onClick={() =>
										setFeaturedStartIndex((prev) =>
											featuredCount ? (prev + 1) % featuredCount : 0,
										)
									}
									className="absolute right-3 top-1/2 z-30 inline-flex h-12 w-12 -translate-y-1/2 items-center justify-center text-white/90 drop-shadow transition hover:text-white"
									aria-label="Sonraki"
								>
									<ChevronRight className="h-9 w-9" />
								</button>
								<div className="overflow-hidden">
									<div
										className={`grid items-stretch gap-4 ${
											featuredPerView === 1
												? 'grid-cols-1'
												: featuredPerView === 2
													? 'grid-cols-2'
													: featuredPerView === 3
														? 'grid-cols-3'
														: 'grid-cols-4'
										}`}
									>
										{Array.from({ length: Math.min(featuredPerView, products.length) }).map(
											(_, offset) => {
												const index =
													(safeFeaturedStartIndex + offset) % products.length;
												const product = products[index];
												return (
													<div key={`${product.id}-${index}`} className="h-full">
														<ProductCard product={product} variant="compact" />
													</div>
												);
											},
										)}
									</div>
								</div>
							</div>
						) : (
							<p className="text-sm text-[var(--neutral-600)]">
								Şu anda öne çıkan ürün bulunmuyor.
							</p>
						)}
					</section>
				</>
			)}
		</div>
	);
}

'use client';

import Link from 'next/link';
import { useMemo, useState } from 'react';
import toast from 'react-hot-toast';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

import Button from '@/components/common/Button';
import Spinner from '@/components/common/Spinner';
import api from '@/services/api';

const resolveApiErrorMessage = (error: unknown, fallback: string) => {
  if (!error || typeof error !== 'object') return fallback;
  if (!('response' in error)) return fallback;
  const response = (error as { response?: unknown }).response;
  if (!response || typeof response !== 'object') return fallback;
  if (!('data' in response)) return fallback;
  const data = (response as { data?: unknown }).data;
  if (!data || typeof data !== 'object') return fallback;
  if (!('message' in data)) return fallback;
  const message = (data as { message?: unknown }).message;
  if (Array.isArray(message)) {
    return message.map(String).join(', ');
  }
  if (typeof message === 'string') return message;
  return fallback;
};

type AddressRow = {
  id: number;
  title: string;
  fullName: string;
  phone: string;
  line1: string;
  line2?: string | null;
  city: string;
  district: string;
  postalCode?: string | null;
  country: string;
  isDefaultShipping: boolean;
  isDefaultBilling: boolean;
  createdAt: string;
  updatedAt: string;
};

export default function AccountAddressesPage() {
  const queryClient = useQueryClient();

  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);

  const [form, setForm] = useState({
    title: '',
    fullName: '',
    phone: '',
    line1: '',
    line2: '',
    city: '',
    district: '',
    postalCode: '',
    country: 'TR',
  });

  const {
    data: addresses,
    isLoading,
    isError,
    error,
  } = useQuery<AddressRow[]>({
    queryKey: ['account-addresses'],
    queryFn: async () => {
      const res = await api.get<AddressRow[]>('/customer/addresses');
      return res.data;
    },
  });

  const editingAddress = useMemo(() => {
    if (!addresses || editingId === null) return null;
    return addresses.find((a) => a.id === editingId) ?? null;
  }, [addresses, editingId]);

  const openCreate = () => {
    setEditingId(null);
    setForm({
      title: '',
      fullName: '',
      phone: '',
      line1: '',
      line2: '',
      city: '',
      district: '',
      postalCode: '',
      country: 'TR',
    });
    setIsFormOpen(true);
  };

  const openEdit = (addr: AddressRow) => {
    setEditingId(addr.id);
    setForm({
      title: addr.title ?? '',
      fullName: addr.fullName ?? '',
      phone: addr.phone ?? '',
      line1: addr.line1 ?? '',
      line2: addr.line2 ?? '',
      city: addr.city ?? '',
      district: addr.district ?? '',
      postalCode: addr.postalCode ?? '',
      country: addr.country ?? 'TR',
    });
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setIsFormOpen(false);
  };

  const createMutation = useMutation({
    mutationFn: async () => {
      const payload = {
        title: form.title.trim(),
        fullName: form.fullName.trim(),
        phone: form.phone.trim(),
        line1: form.line1.trim(),
        line2: form.line2.trim() || undefined,
        city: form.city.trim(),
        district: form.district.trim(),
        postalCode: form.postalCode.trim() || undefined,
        country: form.country.trim() || 'TR',
      };

      if (!payload.title || !payload.fullName || !payload.phone || !payload.line1 || !payload.city || !payload.district) {
        throw new Error('Lütfen zorunlu alanları doldurun.');
      }

      const res = await api.post<AddressRow>('/customer/addresses', payload);
      return res.data;
    },
    onSuccess: async () => {
      toast.success('Adres eklendi.');
      closeForm();
      await queryClient.invalidateQueries({ queryKey: ['account-addresses'] });
    },
    onError: (err: unknown) => {
      toast.error(resolveApiErrorMessage(err, 'Adres eklenemedi.'));
    },
  });

  const updateMutation = useMutation({
    mutationFn: async () => {
      if (!editingId) return;
      const res = await api.patch<AddressRow>(`/customer/addresses/${editingId}`, {
        title: form.title.trim() || undefined,
        fullName: form.fullName.trim() || undefined,
        phone: form.phone.trim() || undefined,
        line1: form.line1.trim() || undefined,
        line2: form.line2.trim() || undefined,
        city: form.city.trim() || undefined,
        district: form.district.trim() || undefined,
        postalCode: form.postalCode.trim() || undefined,
        country: form.country.trim() || undefined,
      });
      return res.data;
    },
    onSuccess: async () => {
      toast.success('Adres güncellendi.');
      closeForm();
      await queryClient.invalidateQueries({ queryKey: ['account-addresses'] });
    },
    onError: (err: unknown) => {
      toast.error(resolveApiErrorMessage(err, 'Adres güncellenemedi.'));
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: number) => {
      await api.delete(`/customer/addresses/${id}`);
    },
    onSuccess: async () => {
      toast.success('Adres silindi.');
      await queryClient.invalidateQueries({ queryKey: ['account-addresses'] });
    },
    onError: (err: unknown) => {
      toast.error(resolveApiErrorMessage(err, 'Adres silinemedi.'));
    },
  });

  const setDefaultMutation = useMutation({
    mutationFn: async (payload: { id: number; type: 'shipping' | 'billing' }) => {
      const res = await api.patch<AddressRow>(`/customer/addresses/${payload.id}/default`, {
        type: payload.type,
      });
      return res.data;
    },
    onSuccess: async () => {
      toast.success('Varsayılan adres güncellendi.');
      await queryClient.invalidateQueries({ queryKey: ['account-addresses'] });
    },
    onError: (err: unknown) => {
      toast.error(resolveApiErrorMessage(err, 'Varsayılan adres güncellenemedi.'));
    },
  });

  if (isLoading) {
    return (
      <div className="mx-auto flex max-w-6xl flex-col px-4 py-6 md:px-6 md:py-10">
        <Spinner fullscreen />
      </div>
    );
  }

  if (isError) {
    const message = resolveApiErrorMessage(error, 'Adresler yüklenemedi.');

    return (
      <div className="mx-auto flex max-w-6xl flex-col gap-4 px-4 py-6 md:px-6 md:py-10">
        <h1 className="text-2xl font-semibold text-[var(--primary-800)] md:text-3xl">Adreslerim</h1>
        <section className="space-y-3 rounded-[var(--radius-2xl)] border border-[var(--error-600)]/20 bg-[var(--error-100)] px-4 py-6 md:px-6">
          <p className="text-sm text-[var(--error-600)] md:text-base">{message}</p>
        </section>
      </div>
    );
  }

  return (
    <div className="mx-auto flex max-w-6xl flex-col gap-6 px-4 py-6 md:px-6 md:py-10">
      <header className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-semibold text-[var(--primary-800)] md:text-3xl">Adreslerim</h1>
          <p className="mt-1 text-xs text-[var(--neutral-600)] md:text-sm">
            Teslimat ve fatura adreslerinizi yönetin.
          </p>
        </div>
        <Button type="button" onClick={openCreate}>
          Yeni adres
        </Button>
      </header>

      {!addresses || addresses.length === 0 ? (
        <section className="space-y-3 rounded-[var(--radius-2xl)] border border-[var(--neutral-200)] bg-white px-4 py-6 shadow-[var(--shadow-md)] md:px-6">
          <p className="text-sm text-[var(--neutral-600)] md:text-base">Kayıtlı adres yok.</p>
          <Button type="button" variant="secondary" onClick={openCreate}>
            İlk adresi ekle
          </Button>
        </section>
      ) : (
        <section className="grid gap-4 md:grid-cols-2">
          {addresses.map((addr) => (
            <div
              key={addr.id}
              className="rounded-[var(--radius-2xl)] border border-[var(--neutral-200)] bg-white px-4 py-5 shadow-[var(--shadow-md)]"
            >
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div>
                  <p className="text-sm font-semibold text-[var(--primary-800)]">{addr.title}</p>
                  <p className="mt-1 text-xs text-[var(--neutral-600)]">
                    {addr.fullName} • {addr.phone}
                  </p>
                </div>

                <div className="flex flex-wrap items-center gap-2">
                  {addr.isDefaultShipping && (
                    <span className="rounded-full border border-[var(--neutral-200)] bg-[var(--neutral-50)] px-2 py-1 text-[10px] font-semibold uppercase tracking-[0.12em] text-[var(--primary-800)]">
                      Default teslimat
                    </span>
                  )}
                  {addr.isDefaultBilling && (
                    <span className="rounded-full border border-[var(--neutral-200)] bg-[var(--neutral-50)] px-2 py-1 text-[10px] font-semibold uppercase tracking-[0.12em] text-[var(--primary-800)]">
                      Default fatura
                    </span>
                  )}
                </div>
              </div>

              <div className="mt-4 space-y-1 text-sm text-[var(--neutral-700)]">
                <p>{addr.line1}</p>
                {addr.line2 && <p>{addr.line2}</p>}
                <p>
                  {addr.district} / {addr.city}
                  {addr.postalCode ? `, ${addr.postalCode}` : ''}
                </p>
                <p className="text-xs text-[var(--neutral-500)]">{addr.country}</p>
              </div>

              <div className="mt-5 flex flex-wrap items-center gap-2">
                <button
                  type="button"
                  onClick={() => setDefaultMutation.mutate({ id: addr.id, type: 'shipping' })}
