    queryKey: ['admin-categories', { page, pageSize }],
    queryFn: async () => {
      const res = await api.get<PaginatedCategories>('/categories', {
        params: {
          page,
          pageSize,
        },
      });
      return res.data;
    },
  });

  const categories = categoriesPayload?.data ?? [];
  const meta = categoriesPayload?.meta;

  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState({
    name: '',
    slug: '',
    parentId: '',
    orderIndex: '0',
    isActive: true,
  });

  const {
    data: categoriesTree,
    isLoading,
    isError,
  } = useQuery<CategoryTreeNode[]>({
    queryKey: ['admin-categories-tree'],
    queryFn: async () => {
      const res = await api.get<CategoryTreeNode[]>('/categories/tree');
      return res.data;
    },
  });

  // Flatten tree for table display
  const flattenCategories = (tree: CategoryTreeNode[], level = 0): FlatCategory[] => {
    const result: FlatCategory[] = [];
    for (const cat of tree) {
      result.push({
        id: cat.id,
        name: cat.name,
        slug: cat.slug,
        parentId: cat.parentId,
        isActive: cat.isActive,
        orderIndex: cat.orderIndex,
        level,
        createdAt: cat.createdAt,
        updatedAt: cat.updatedAt,
        archivedAt: cat.archivedAt,
      });
      if (cat.children) {
        result.push(...flattenCategories(cat.children, level + 1));
      }
    }
    return result;
  };

  const flatCategories = useMemo(() => {
    return flattenCategories(categoriesTree || []);
  }, [categoriesTree]);

  const categoryById = useMemo(() => {
    const map = new Map<number, FlatCategory>();
    for (const c of flatCategories) {
      map.set(c.id, c);
    }
    return map;
  }, [flatCategories]);

  // For parent selectors, create list excluding current category if editing
  const availableParents = useMemo(() => {
    const categories = flatCategories.filter(
      (cat) => editingId === null || cat.id !== editingId
    );
    return categories.map((cat) => ({
      id: cat.id,
      name: cat.name,
      level: cat.level,
    }));
  }, [flatCategories, editingId]);

  const createMutation = useMutation({
    mutationFn: async () => {
      const orderIndex = Number(createForm.orderIndex);
      const parentId = createForm.parentId ? Number(createForm.parentId) : undefined;

      if (!createForm.name.trim()) {
        throw new Error('Kategori adı zorunludur.');
      }
      if (Number.isNaN(orderIndex) || orderIndex < 0) {
        throw new Error('Sıra değeri geçersiz.');
      }
      if (parentId !== undefined && (Number.isNaN(parentId) || parentId < 1)) {
        throw new Error('Üst kategori seçimi geçersiz.');
      }

      await api.post('/categories', {
        name: createForm.name.trim(),
        slug: createForm.slug.trim() || undefined,
        parentId,
        isActive: createForm.isActive,
        orderIndex,
      });
    },
    onSuccess: async () => {
      toast.success('Kategori oluşturuldu.');
      setCreateForm({ name: '', slug: '', parentId: '', orderIndex: '0', isActive: true });
      await queryClient.invalidateQueries({ queryKey: ['admin-categories-tree'] });
      await queryClient.invalidateQueries({ queryKey: ['admin-categories'] });
    },
    onError: (error: unknown) => {
      toast.error(resolveApiErrorMessage(error, 'Kategori oluşturulamadı.'));
    },
  });

  const updateMutation = useMutation({
    mutationFn: async (categoryId: number) => {
      const orderIndex = Number(editForm.orderIndex);
      const parentId = editForm.parentId ? Number(editForm.parentId) : null;

      if (!editForm.name.trim()) {
        throw new Error('Kategori adı zorunludur.');
      }
      if (Number.isNaN(orderIndex) || orderIndex < 0) {
        throw new Error('Sıra değeri geçersiz.');
      }
      if (parentId !== null && (Number.isNaN(parentId) || parentId < 1)) {
        throw new Error('Üst kategori seçimi geçersiz.');
      }

      await api.patch(`/categories/${categoryId}`, {
        name: editForm.name.trim(),
        slug: editForm.slug.trim() || undefined,
        parentId: parentId || undefined,
        isActive: editForm.isActive,
        orderIndex,
      });
    },
    onSuccess: async () => {
      toast.success('Kategori güncellendi.');
      setEditingId(null);
      await queryClient.invalidateQueries({ queryKey: ['admin-categories-tree'] });
      await queryClient.invalidateQueries({ queryKey: ['admin-categories'] });
    },
    onError: (error: unknown) => {
      toast.error(resolveApiErrorMessage(error, 'Kategori güncellenemedi.'));
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (categoryId: number) => {
      await api.delete(`/categories/${categoryId}`);
    },
    onSuccess: async () => {
      toast.success('Kategori arşivlendi.');
      await queryClient.invalidateQueries({ queryKey: ['admin-categories-tree'] });
      await queryClient.invalidateQueries({ queryKey: ['admin-categories'] });
    },
    onError: (error: unknown) => {
      toast.error(resolveApiErrorMessage(error, 'Kategori arşivlenemedi.'));
    },
  });

  const beginEdit = (category: CategoryRow) => {
    setEditingId(category.id);
    setEditForm({
      name: category.name,
      slug: category.slug,
      parentId: category.parentId ? String(category.parentId) : '',
      orderIndex: String(category.orderIndex ?? 0),
      isActive: category.isActive,
    });
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditForm({ name: '', slug: '', parentId: '', orderIndex: '0', isActive: true });
  };

  const handleCreate = (event: FormEvent) => {
    event.preventDefault();
    createMutation.mutate();
  };

  return (
    <div className="space-y-6">
      <section className="rounded-[32px] border border-[#1A3C34]/10 bg-white/90 px-6 py-6 shadow-[0_30px_90px_rgba(26,60,52,0.12)]">
        <div className="flex flex-wrap items-end justify-between gap-4">
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
              Katalog
            </p>
            <h1 className="text-3xl font-serif text-[#1A3C34] md:text-4xl">
              Kategori yönetimi
            </h1>
            <p className="text-sm text-[#5C5C5C]">
              Gerçek kategori CRUD akışı (ADMIN yetkisi ile) backend tarafına bağlıdır.
            </p>
          </div>
          <div className="inline-flex items-center gap-2 rounded-full border border-[#1A3C34]/10 bg-white px-4 py-2 text-[11px] font-semibold uppercase tracking-[0.25em] text-[#1A3C34]/70">
            <LayoutGrid className="h-4 w-4" />
            Toplam: {meta?.total ?? flatCategories?.length ?? 0}
          </div>
        </div>
      </section>

      <section className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)]">
        <form
          onSubmit={handleCreate}
          className="space-y-4 rounded-[28px] border border-[#E0D7C6] bg-white/90 px-6 py-6 shadow-[0_20px_60px_rgba(26,60,52,0.08)]"
        >
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
              Yeni kategori
            </p>
            <h2 className="mt-2 text-2xl font-serif text-[#1A3C34]">
              Koleksiyon oluştur
            </h2>
          </div>

          <div className="grid gap-3">
            <div className="space-y-1">
              <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                Ad
              </label>
              <input
                value={createForm.name}
                onChange={(e) =>
                  setCreateForm((p) => ({ ...p, name: e.target.value }))
                }
                className="h-11 w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                placeholder="örn: Piyanolar"
                required
              />
            </div>

            <div className="space-y-1">
              <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                Slug (opsiyonel)
              </label>
              <input
                value={createForm.slug}
                onChange={(e) => setCreateForm((p) => ({ ...p, slug: e.target.value }))}
                className="h-11 w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                placeholder="örn: piyanolar"
              />
            </div>

            <div className="space-y-1">
              <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                Üst Kategori (opsiyonel)
              </label>
              <select
                value={createForm.parentId}
                onChange={(e) =>
                  setCreateForm((p) => ({ ...p, parentId: e.target.value }))
                }
                className="h-11 w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
              >
                <option value="">Kök kategori (üst yok)</option>
                {availableParents.map((cat) => (
                  <option key={cat.id} value={String(cat.id)}>
                    {'  '.repeat(cat.level)}
                    {cat.name}
                  </option>
                ))}
              </select>
            </div>

            <div className="grid gap-3 md:grid-cols-2">
              <div className="space-y-1">
                <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                  Sıra
                </label>
                <input
                  value={createForm.orderIndex}
                  onChange={(e) =>
                    setCreateForm((p) => ({
                      ...p,
                      orderIndex: e.target.value,
                    }))
                  }
                  className="h-11 w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                  inputMode="numeric"
                />
              </div>
              <div className="space-y-1">
                <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                  Durum
                </label>
                <select
                  value={createForm.isActive ? 'active' : 'inactive'}
                  onChange={(e) =>
                    setCreateForm((p) => ({
                      ...p,
                      isActive: e.target.value === 'active',
                    }))
                  }
                  className="h-11 w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                >
                  <option value="active">Aktif</option>
                  <option value="inactive">Pasif</option>
                </select>
              </div>
            </div>
          </div>

          <Button
            type="submit"
            className="w-full"
            disabled={createMutation.isPending}
            isLoading={createMutation.isPending}
          >
            Kategoriyi kaydet
          </Button>
        </form>

        <section className="rounded-[28px] border border-[#E0D7C6] bg-white/90 px-6 py-6 shadow-[0_20px_60px_rgba(26,60,52,0.08)]">
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
              Liste
            </p>
            <h2 className="mt-2 text-2xl font-serif text-[#1A3C34]">
              Kategoriler
            </h2>
          </div>

          <div className="mt-6 overflow-hidden rounded-2xl border border-[#1A3C34]/10 bg-white">
            <div className="grid grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)_minmax(0,0.7fr)_minmax(0,0.7fr)_minmax(0,0.6fr)_minmax(0,1fr)] gap-3 border-b border-[#E5E5E0] px-4 py-3 text-[10px] font-semibold uppercase tracking-[0.25em] text-[#1A3C34]/60">
              <span>Kategori</span>
              <span>Slug</span>
              <span>Sıra</span>
              <span>Üst Kat.</span>
              <span>Durum</span>
              <span className="text-right">Aksiyon</span>
            </div>
            <div className="divide-y divide-[#F0F0EA]">
              {(isLoading || isListLoading) && (
                <div className="px-4 py-8">
                  <Spinner fullscreen />
                </div>
              )}

              {(isError || isListError) && !(isLoading || isListLoading) && (
                <div className="px-4 py-4 text-sm text-red-700">
                  Kategoriler yüklenemedi.
                </div>
              )}

              {!(isLoading || isListLoading) && !(isError || isListError) && (!categories || categories.length === 0) && (
                <div className="px-4 py-4 text-sm text-[#5C5C5C]">
                  Kategori bulunamadı.
                </div>
              )}

              {!(isLoading || isListLoading) && !(isError || isListError) && categories?.map((c) => {
                const isEditing = editingId === c.id;
                const flat = categoryById.get(c.id);
                const level = flat?.level ?? 0;
                return (
                  <div
                    key={c.id}
                    className="grid grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)_minmax(0,0.7fr)_minmax(0,0.7fr)_minmax(0,0.6fr)_minmax(0,1fr)] gap-3 px-4 py-3 text-sm text-[#1A3C34]"
                  >
                    <div className="min-w-0">
                      {!isEditing ? (
                        <div>
                          <p className="truncate font-semibold" style={{ paddingLeft: `${level * 12}px` }}>
                            {level > 0 && (
                              <ChevronRight className="inline h-3 w-3 mr-1" />
                            )}
                            {c.name}
                          </p>
                          <p className="truncate text-xs text-[#5C5C5C]">ID: {c.id}</p>
                        </div>
                      ) : (
                        <input
                          value={editForm.name}
                          onChange={(e) =>
                            setEditForm((p) => ({ ...p, name: e.target.value }))
                          }
                          className="h-9 w-full rounded-xl border border-[#E5E5E0] bg-white px-3 text-sm outline-none"
                        />
                      )}
                    </div>

                    <div className="min-w-0">
                      {!isEditing ? (
                        <span className="truncate text-sm text-[#5C5C5C]">{c.slug}</span>
                      ) : (
                        <input
                          value={editForm.slug}
                          onChange={(e) =>
                            setEditForm((p) => ({
                              ...p,
                              slug: e.target.value,
                            }))
                          }
                          className="h-9 w-full rounded-xl border border-[#E5E5E0] bg-white px-3 text-xs outline-none"
                        />
                      )}
                    </div>

                    <div>
                      {!isEditing ? (
                        <span className="text-sm text-[#5C5C5C]">{c.orderIndex}</span>
                      ) : (
                        <input
                          value={editForm.orderIndex}
                          onChange={(e) =>
                            setEditForm((p) => ({
                              ...p,
                              orderIndex: e.target.value,
                            }))
                          }
                          className="h-9 w-full rounded-xl border border-[#E5E5E0] bg-white px-3 text-xs outline-none"
                          inputMode="numeric"
                        />
                      )}
                    </div>

                    <div>
                      {!isEditing ? (
                        <span className="text-sm text-[#5C5C5C]">
                          {c.parentId ? categoryById.get(c.parentId)?.name || '-' : '-'}
                        </span>
                      ) : (
                        <select
                          value={editForm.parentId}
                          onChange={(e) =>
                            setEditForm((p) => ({
                              ...p,
                              parentId: e.target.value,
                            }))
                          }
                          className="h-9 w-full rounded-xl border border-[#E5E5E0] bg-white px-2 text-xs outline-none"
                        >
                          <option value="">Kök</option>
                          {availableParents.map((cat) => (
                            <option key={cat.id} value={String(cat.id)}>
                              {'  '.repeat(cat.level)}
                              {cat.name}
                            </option>
                          ))}
                        </select>
                      )}
                    </div>

                    <div className="flex items-center justify-end gap-2">
                      {!isEditing ? (
                        <>
                          <button
                            type="button"
                            onClick={() => beginEdit(c)}
                            className="inline-flex items-center gap-2 rounded-full border border-[#1A3C34]/15 bg-white px-3 py-2 text-[10px] font-semibold uppercase tracking-[0.25em] text-[#1A3C34]"
                          >
                            <Pencil className="h-4 w-4" />
                            Düzenle
                          </button>
                          <button
                            type="button"
                            onClick={() => deleteMutation.mutate(c.id)}
                            disabled={deleteMutation.isPending}
                            className="inline-flex items-center gap-2 rounded-full border border-[#B04B4B]/30 bg-white px-3 py-2 text-[10px] font-semibold uppercase tracking-[0.25em] text-[#B04B4B] disabled:opacity-60"
                          >
                            <Archive className="h-4 w-4" />
                            Arşivle
                          </button>
                        </>
                      ) : (
                        <>
                          <button
                            type="button"
                            onClick={() => editingId && updateMutation.mutate(editingId)}
                            disabled={updateMutation.isPending}
                            className="inline-flex items-center gap-2 rounded-full bg-[#1A3C34] px-3 py-2 text-[10px] font-semibold uppercase tracking-[0.25em] text-white disabled:opacity-60"
                          >
                            <Save className="h-4 w-4" />
                            Kaydet
                          </button>
                          <button
                            type="button"
                            onClick={cancelEdit}
                            className="inline-flex items-center gap-2 rounded-full border border-[#1A3C34]/15 bg-white px-3 py-2 text-[10px] font-semibold uppercase tracking-[0.25em] text-[#1A3C34]"
                          >
                            <X className="h-4 w-4" />
                            İptal
                          </button>
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {!(isLoading || isListLoading) && !(isError || isListError) && meta && meta.totalPages > 1 && (
            <div className="mt-6 flex flex-wrap items-center justify-between gap-3 border-t border-[#E5E5E0] pt-4 text-xs text-[#5C5C5C]">
              <span className="text-[11px] font-semibold uppercase tracking-[0.25em] text-[#1A3C34]/60">
                Sayfa {meta.page} / {meta.totalPages}
              </span>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  disabled={meta.page <= 1}
                  className="inline-flex h-11 items-center gap-2 rounded-[var(--radius-md)] border border-[#E5E5E0] bg-white px-4 text-xs font-semibold uppercase tracking-[0.2em] text-[#1A3C34] shadow-sm disabled:cursor-not-allowed disabled:opacity-50"
                >
                  Önceki
                </button>
                <button
                  type="button"
                  onClick={() => setPage((p) => Math.min(meta.totalPages, p + 1))}
                  disabled={meta.page >= meta.totalPages}
                  className="inline-flex h-11 items-center gap-2 rounded-[var(--radius-md)] border border-[#1A3C34]/10 bg-[#1A3C34] px-4 text-xs font-semibold uppercase tracking-[0.2em] text-white shadow-sm disabled:cursor-not-allowed disabled:opacity-50"
                >
                  Sonraki
                </button>
              </div>
            </div>
          )}
        </section>
      </section>
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';
import toast from 'react-hot-toast';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

import ConflictResolutionModal from '@/components/common/ConflictResolutionModal';
import Spinner from '@/components/common/Spinner';
import PaginationControls from '@/components/common/PaginationControls';
import { useCapabilities } from '@/hooks/useCapabilities';
import { isConflictError, resolveApiErrorMessage } from '@/lib/api-errors';
import api from '@/services/api';
import { formatDate, formatPrice } from '@/utils/helpers';

type PaginationMeta = {
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
};

type PayoutRow = {
  id: number;
  beneficiaryUserId: number;
  amountCents: number;
  status: string;
  requestedAt: string;
  approvedAt?: string | null;
  completedAt?: string | null;
};

type PaginatedPayouts = {
  data: PayoutRow[];
  meta: PaginationMeta;
};

const statusBadge = (status: string) => {
  const key = String(status ?? '').trim().toLowerCase();
  if (key === 'pending') return 'bg-[#FFF7E6] text-[#7A4B00]';
  if (key === 'approved') return 'bg-[#E8F1FF] text-[#0B3B91]';
  if (key === 'completed') return 'bg-[#E6FBF2] text-[#0F5132]';
  return 'bg-[#F3EEE3] text-[#3E2723]';
};

export default function AdminPlatformPayoutsPage() {
  const queryClient = useQueryClient();
  const { can } = useCapabilities();

  const [status, setStatus] = useState<'pending' | 'approved' | 'completed' | ''>('pending');
  const [page, setPage] = useState(1);
  const [pageSize] = useState(20);
  const [conflictDetail, setConflictDetail] = useState<string | null>(null);
  const [markPaidTargetId, setMarkPaidTargetId] = useState<number | null>(null);

  const {
    data: payload,
    isLoading,
    isError,
    error,
  } = useQuery<PaginatedPayouts>({
    queryKey: ['platform-payouts', { status, page, pageSize }],
    queryFn: async () => {
      const res = await api.get<PaginatedPayouts>('/platform/finance/payouts', {
        params: {
          status: status || undefined,
          page,
          pageSize,
        },
      });
      return res.data;
    },
  });

  const items = payload?.data ?? [];
  const meta = payload?.meta;

  const approveMutation = useMutation({
    mutationFn: async (id: number) => {
      const res = await api.patch(`/platform/finance/payouts/${id}/approve`);
      return res.data;
    },
    onSuccess: async () => {
      toast.success('Payout onaylandı.');
      await queryClient.invalidateQueries({ queryKey: ['platform-payouts'] });
    },
    onError: (err: unknown) => {
      if (isConflictError(err)) {
        setConflictDetail(
          resolveApiErrorMessage(
            err,
            'Payout durumu baska bir admin tarafindan degistirildi.',
          ),
        );
        return;
      }
      toast.error(resolveApiErrorMessage(err, 'Payout onaylanamadı.'));
    },
  });

  const completeMutation = useMutation({
    mutationFn: async (id: number) => {
      const res = await api.patch(`/platform/finance/payouts/${id}/complete`);
      return res.data;
    },
    onSuccess: async () => {
      toast.success('Payout tamamlandı.');
      await queryClient.invalidateQueries({ queryKey: ['platform-payouts'] });
    },
    onError: (err: unknown) => {
      if (isConflictError(err)) {
        setConflictDetail(
          resolveApiErrorMessage(
            err,
            'Payout durumu baska bir admin tarafindan degistirildi.',
          ),
        );
        return;
      }
      toast.error(resolveApiErrorMessage(err, 'Payout tamamlanamadı.'));
    },
  });

  const rejectMutation = useMutation({
    mutationFn: async (id: number) => {
      const res = await api.patch(`/platform/finance/payouts/${id}/reject`);
      return res.data;
    },
    onSuccess: async () => {
      toast.success('Payout reddedildi.');
      await queryClient.invalidateQueries({ queryKey: ['platform-payouts'] });
    },
    onError: (err: unknown) => {
      if (isConflictError(err)) {
        setConflictDetail(
          resolveApiErrorMessage(
            err,
            'Payout durumu baska bir admin tarafindan degistirildi.',
          ),
        );
        return;
      }
      toast.error(resolveApiErrorMessage(err, 'Payout reddedilemedi.'));
    },
  });

  const summary = useMemo(() => {
    const totalAmount = items.reduce((acc, r) => acc + (Number(r.amountCents) || 0), 0);
    return {
      count: items.length,
      totalAmountCents: totalAmount,
    };
  }, [items]);

  if (isLoading) {
    return (
      <div className="mx-auto flex max-w-6xl flex-col px-4 py-10 md:px-6">
        <Spinner fullscreen />
      </div>
    );
  }

  if (isError) {
    const message = resolveApiErrorMessage(error, 'Payout listesi yüklenemedi.');
    return (
      <div className="space-y-4">
        <h1 className="text-3xl font-serif text-[var(--primary-800)]">Payout Yönetimi</h1>
        <section className="space-y-3 rounded-[var(--radius-2xl)] border border-[var(--error-600)]/20 bg-[var(--error-100)] px-4 py-6 md:px-6">
          <p className="text-sm text-[var(--error-600)] md:text-base">{message}</p>
        </section>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <section className="border-b border-[var(--neutral-200)] pb-6">
        <div className="flex flex-wrap items-end justify-between gap-4">
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[var(--neutral-500)]">
              Finans
            </p>
            <h1 className="mt-2 text-3xl font-serif text-[var(--primary-800)] md:text-4xl">
              Payout Yönetimi
            </h1>
            <p className="mt-2 text-sm text-[var(--neutral-600)]">
              Satıcı payout taleplerini onaylayın ve EFT sonrası tamamlayın.
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <select
              value={status}
              onChange={(e) => {
                setPage(1);
                setStatus(e.target.value as any);
              }}
              className="h-11 rounded-[var(--radius-lg)] border border-[var(--neutral-200)] bg-white px-4 text-sm"
            >
              <option value="pending">Bekleyen</option>
              <option value="approved">Onaylı</option>
              <option value="completed">Tamamlanan</option>
              <option value="">Tümü</option>
            </select>
          </div>
        </div>
      </section>

      <section className="grid gap-4 md:grid-cols-3">
        <div className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-6 py-5">
          <p className="text-[10px] font-semibold uppercase tracking-[0.25em] text-[var(--neutral-500)]">
            Kayıt
          </p>
          <p className="mt-2 text-2xl font-serif text-[var(--primary-800)]">{summary.count}</p>
        </div>
        <div className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-6 py-5">
          <p className="text-[10px] font-semibold uppercase tracking-[0.25em] text-[var(--neutral-500)]">
            Toplam tutar
          </p>
          <p className="mt-2 text-2xl font-serif text-[var(--primary-800)]">
            {formatPrice(summary.totalAmountCents / 100)}
          </p>
        </div>
        <div className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-6 py-5">
          <p className="text-[10px] font-semibold uppercase tracking-[0.25em] text-[var(--neutral-500)]">
            Sayfa
          </p>
          <p className="mt-2 text-2xl font-serif text-[var(--primary-800)]">
            {meta ? `${meta.page}/${meta.totalPages}` : '-'}
          </p>
        </div>
      </section>

      {items.length === 0 ? (
        <section className="rounded-[var(--radius-2xl)] border border-[var(--neutral-200)] bg-white px-6 py-6">
          <p className="text-sm text-[var(--neutral-600)]">Kayıt bulunamadı.</p>
        </section>
      ) : (
        <section className="overflow-hidden rounded-[var(--radius-2xl)] border border-[var(--neutral-200)] bg-white shadow-[var(--shadow-md)]">
          <div className="overflow-x-auto">
            <table className="w-full min-w-[720px] text-left text-sm">
              <thead className="border-b border-[var(--neutral-200)] bg-[var(--neutral-50)]">
                <tr>
                  <th className="px-4 py-3 text-[11px] font-semibold uppercase tracking-[0.2em] text-[var(--neutral-500)]">ID</th>
                  <th className="px-4 py-3 text-[11px] font-semibold uppercase tracking-[0.2em] text-[var(--neutral-500)]">Satıcı User</th>
                  <th className="px-4 py-3 text-[11px] font-semibold uppercase tracking-[0.2em] text-[var(--neutral-500)]">Tutar</th>
                  <th className="px-4 py-3 text-[11px] font-semibold uppercase tracking-[0.2em] text-[var(--neutral-500)]">Durum</th>
                  <th className="px-4 py-3 text-[11px] font-semibold uppercase tracking-[0.2em] text-[var(--neutral-500)]">Tarih</th>
                  <th className="px-4 py-3 text-right text-[11px] font-semibold uppercase tracking-[0.2em] text-[var(--neutral-500)]">Aksiyon</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--neutral-200)]">
                {items.map((row) => {
                  const canApprove = String(row.status).toLowerCase() === 'pending';
                  const canComplete = String(row.status).toLowerCase() === 'approved';
                  const canReject =
                    String(row.status).toLowerCase() === 'pending' ||
                    String(row.status).toLowerCase() === 'approved';
                  const canMutatePayout = can('MANAGE_PAYOUT');

                  return (
                    <tr key={row.id} className="hover:bg-[var(--neutral-50)]">
                      <td className="px-4 py-3 font-semibold text-[var(--primary-800)]">#{row.id}</td>
                      <td className="px-4 py-3 text-[var(--neutral-700)]">{row.beneficiaryUserId}</td>
                      <td className="px-4 py-3 font-semibold text-[var(--primary-800)]">
                        {formatPrice((row.amountCents ?? 0) / 100)}
                      </td>
                      <td className="px-4 py-3">
                        <span className={`rounded-full px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.18em] ${statusBadge(row.status)}`}>
                          {row.status}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-xs text-[var(--neutral-600)]">
                        {formatDate(row.requestedAt)}
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex justify-end gap-2">
                          <button
                            type="button"
                            disabled={
                              !canMutatePayout ||
                              !canApprove ||
                              approveMutation.isPending ||
                              completeMutation.isPending ||
                              rejectMutation.isPending
                            }
                            onClick={() => {
                              const ok = window.confirm('Bu payout onaylansın mı?');
                              if (!ok) return;
                              approveMutation.mutate(row.id);
                            }}
                            className="inline-flex h-10 items-center justify-center rounded-[var(--radius-lg)] border border-[var(--neutral-200)] bg-white px-4 text-[11px] font-semibold uppercase tracking-[0.2em] text-[var(--primary-800)] disabled:cursor-not-allowed disabled:opacity-50"
                          >
                            Onayla
                          </button>
                          <button
                            type="button"
                            disabled={
                              !canMutatePayout ||
                              !canReject ||
                              approveMutation.isPending ||
                              completeMutation.isPending ||
                              rejectMutation.isPending
                            }
                            onClick={() => {
                              const ok = window.confirm('Bu payout reddedilsin mi?');
                              if (!ok) return;
                              rejectMutation.mutate(row.id);
                            }}
                            className="inline-flex h-10 items-center justify-center rounded-[var(--radius-lg)] border border-red-200 bg-white px-4 text-[11px] font-semibold uppercase tracking-[0.2em] text-red-700 disabled:cursor-not-allowed disabled:opacity-50"
                          >
                            Reddet
                          </button>
                          <button
                            type="button"
                            disabled={
                              !canMutatePayout ||
                              !canComplete ||
                              approveMutation.isPending ||
                              completeMutation.isPending ||
                              rejectMutation.isPending
                            }
                            onClick={() => {
                              setMarkPaidTargetId(row.id);
                            }}
                            className="inline-flex h-10 items-center justify-center rounded-[var(--radius-lg)] bg-[var(--primary-800)] px-4 text-[11px] font-semibold uppercase tracking-[0.2em] text-white disabled:cursor-not-allowed disabled:opacity-50"
                          >
                            Mark as Paid
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </section>
      )}

      {!can('MANAGE_PAYOUT') ? (
        <section className="rounded-[var(--radius-xl)] border border-amber-200 bg-amber-50 px-6 py-4">
          <p className="text-sm text-amber-800">
            Bu hesap payout aksiyonlarini yurutemez (sadece goruntuleme).
          </p>
        </section>
      ) : null}

      {meta && meta.totalPages > 1 && (
        <PaginationControls
          page={meta.page}
          totalPages={meta.totalPages}
          buildHref={(nextPage) => {
            void nextPage;
            return '#';
          }}
        />
      )}

      {meta && meta.totalPages > 1 && (
        <div className="flex items-center justify-center gap-2">
          <button
            type="button"
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={meta.page <= 1}
            className="inline-flex h-10 items-center justify-center rounded-[var(--radius-lg)] border border-[var(--neutral-200)] bg-white px-4 text-[11px] font-semibold uppercase tracking-[0.2em] text-[var(--primary-800)] disabled:cursor-not-allowed disabled:opacity-50"
          >
            Önceki
          </button>
          <button
            type="button"
            onClick={() => setPage((p) => Math.min(meta.totalPages, p + 1))}
            disabled={meta.page >= meta.totalPages}
            className="inline-flex h-10 items-center justify-center rounded-[var(--radius-lg)] border border-[var(--neutral-200)] bg-white px-4 text-[11px] font-semibold uppercase tracking-[0.2em] text-[var(--primary-800)] disabled:cursor-not-allowed disabled:opacity-50"
          >
            Sonraki
          </button>
        </div>
      )}

      {markPaidTargetId !== null ? (
        <div className="fixed inset-0 z-50">
          <button
            type="button"
            onClick={() => setMarkPaidTargetId(null)}
            className="absolute inset-0 bg-black/40"
            aria-label="Modali kapat"
          />
          <div className="absolute left-1/2 top-1/2 w-[92vw] max-w-lg -translate-x-1/2 -translate-y-1/2 rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-6 py-6 shadow-[var(--shadow-lg)]">
            <h3 className="text-lg font-semibold text-[var(--primary-800)]">Mark as Paid</h3>
            <p className="mt-3 text-sm text-[var(--neutral-700)]">
              Bu islem immutable ledger kaydi olusturacaktir. Devam etmek istiyor musunuz?
            </p>
            <p className="mt-2 text-xs text-[var(--neutral-600)]">
              Payout #{markPaidTargetId} durumu geri alinmayacak sekilde guncellenecektir.
            </p>
            <div className="mt-5 flex justify-end gap-2">
              <button
                type="button"
                onClick={() => setMarkPaidTargetId(null)}
                className="inline-flex h-10 items-center justify-center rounded-[var(--radius-lg)] border border-[var(--neutral-200)] bg-white px-4 text-[11px] font-semibold uppercase tracking-[0.18em] text-[var(--primary-800)]"
              >
                Vazgec
              </button>
              <button
                type="button"
                onClick={() => {
                  const targetId = markPaidTargetId;
                  if (!targetId) return;
                  completeMutation.mutate(targetId, {
                    onSuccess: () => {
                      setMarkPaidTargetId(null);
                    },
                  });
                }}
                disabled={completeMutation.isPending}
                className="inline-flex h-10 items-center justify-center rounded-[var(--radius-lg)] bg-[var(--primary-800)] px-4 text-[11px] font-semibold uppercase tracking-[0.18em] text-white disabled:cursor-not-allowed disabled:opacity-50"
              >
                Evet, Onayla
              </button>
            </div>
          </div>
        </div>
      ) : null}

      <ConflictResolutionModal
        isOpen={Boolean(conflictDetail)}
        detail={conflictDetail ?? undefined}
        onClose={() => setConflictDetail(null)}
        onRefresh={() => {
          setConflictDetail(null);
          void queryClient.invalidateQueries({ queryKey: ['platform-payouts'] });
        }}
      />
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';
import toast from 'react-hot-toast';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import {
  Activity,
  CheckCircle2,
  ChevronLeft,
  ChevronRight,
  ClipboardList,
  Clock,
  Package,
  PackageCheck,
  RefreshCw,
  Truck,
  X,
  XCircle,
  AlertTriangle,
} from 'lucide-react';

import ConflictResolutionModal from '@/components/common/ConflictResolutionModal';
import Spinner from '@/components/common/Spinner';
import { isConflictError, resolveApiErrorMessage } from '@/lib/api-errors';
import api from '@/services/api';
import { formatDate, formatPrice } from '@/utils/helpers';

/* ─── Types ──────────────────────────────────────────────── */
interface OrderRow {
  id: number; customerId: number; totalAmountCents: number;
  statusKey: string; source: string; createdByUserId: number; createdAt: string;
}
interface OrderItemRow {
  id: number; productId: number; productName?: string;
  quantity: number; unitPriceCents: number; totalAmountCents: number;
}
interface OrderDetail {
  id: number; customerId: number; totalAmountCents: number;
  statusKey: string; source: string; createdByUserId: number; createdAt: string;
  notes?: string; items: OrderItemRow[];
}
interface PaymentRow {
  id: number; amountCents: number; method: string; reference?: string; createdAt: string;
}
interface OrderStatusRow {
  id: number; key: string; label: string; orderIndex: number; isFinal: boolean; isDefault: boolean;
}
interface PaginationMeta { total: number; page: number; pageSize: number; totalPages: number; }
interface PaginatedOrders { data: OrderRow[]; meta: PaginationMeta; }

/* ─── Helpers ────────────────────────────────────────────── */
function getStatusStyle(key: string) {
  const k = key.trim().toUpperCase();
  if (k.includes('NEW')) return { bg: 'bg-blue-50', text: 'text-blue-700', icon: Clock };
  if (k.includes('PAID')) return { bg: 'bg-green-50', text: 'text-green-700', icon: CheckCircle2 };
  if (k.includes('PREP')) return { bg: 'bg-amber-50', text: 'text-amber-700', icon: PackageCheck };
  if (k.includes('SHIP')) return { bg: 'bg-violet-50', text: 'text-violet-700', icon: Truck };
  if (k.includes('DELIV') || k.includes('COMP')) return { bg: 'bg-emerald-50', text: 'text-emerald-700', icon: CheckCircle2 };
  if (k.includes('CANCEL')) return { bg: 'bg-red-50', text: 'text-red-700', icon: XCircle };
  if (k.includes('PROCESS')) return { bg: 'bg-purple-50', text: 'text-purple-700', icon: Activity };
  return { bg: 'bg-gray-50', text: 'text-gray-600', icon: Clock };
}

function StatusBadge({ status }: { status: string }) {
  const { bg, text, icon: Icon } = getStatusStyle(status);
  return (
    <span className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] font-semibold ${bg} ${text}`}>
      <Icon className="h-3 w-3" />{status}
    </span>
  );
}

function SourceBadge({ source }: { source: string }) {
  const map: Record<string, string> = { POS: 'POS', MOBILE: 'Mobil', WEB: 'Web', MANUAL: 'Manuel', ONLINE: 'Online' };
  return <span className="rounded text-[11px] font-medium text-gray-500">{map[source] ?? source}</span>;
}

/* ─── Page ───────────────────────────────────────────────── */
export default function AdminOrdersPage() {
  const queryClient = useQueryClient();
  const [selectedOrderId, setSelectedOrderId] = useState<number | null>(null);
  const [source, setSource] = useState('');
  const [page, setPage] = useState(1);
  const pageSize = 20;
  const [conflictDetail, setConflictDetail] = useState<string | null>(null);

  const { data: ordersPayload, isLoading, isError } = useQuery<PaginatedOrders>({
    queryKey: ['admin-orders', { page, pageSize, source }],
    queryFn: async () => (await api.get<PaginatedOrders>('/platform/orders', {
      params: { source: source || undefined, page, pageSize },
    })).data,
  });

  const { data: statuses, isLoading: isStatusesLoading, isError: isStatusesError } = useQuery<OrderStatusRow[]>({
    queryKey: ['admin-order-statuses'],
    queryFn: async () => (await api.get<OrderStatusRow[]>('/order-status')).data,
  });

  const { data: orderDetail, isLoading: isDetailLoading, isError: isDetailError } = useQuery<OrderDetail>({
    queryKey: ['admin-order-detail', selectedOrderId],
    enabled: typeof selectedOrderId === 'number',
    queryFn: async () => (await api.get<OrderDetail>(`/orders/${selectedOrderId}`)).data,
  });

  const { data: payments, isLoading: isPaymentsLoading, isError: isPaymentsError } = useQuery<PaymentRow[]>({
    queryKey: ['admin-order-payments', selectedOrderId],
    enabled: typeof selectedOrderId === 'number',
    queryFn: async () => (await api.get<PaymentRow[]>(`/orders/${selectedOrderId}/payments`)).data,
  });

  const orders = ordersPayload?.data ?? [];
  const meta = ordersPayload?.meta;

  const kpis = useMemo(() => {
    const byStatus = orders.reduce<Record<string, number>>((acc, o) => {
      const k = o.statusKey.toUpperCase();
      acc[k] = (acc[k] ?? 0) + 1;
      return acc;
    }, {});
    return {
      total: meta?.total ?? orders.length,
      newCount: Object.entries(byStatus).filter(([k]) => k.includes('NEW')).reduce((s, [, v]) => s + v, 0),
      preparingCount: Object.entries(byStatus).filter(([k]) => k.includes('PREP')).reduce((s, [, v]) => s + v, 0),
      deliveredCount: Object.entries(byStatus).filter(([k]) => k.includes('DELIV') || k.includes('COMP')).reduce((s, [, v]) => s + v, 0),
    };
  }, [orders, meta?.total]);

  const updateStatus = useMutation({
    mutationFn: async (nextStatusKey: string) => {
      if (!selectedOrderId) return;
      await api.patch(`/orders/${selectedOrderId}`, { statusKey: nextStatusKey });
    },
    onError: (err: unknown) => {
      if (isConflictError(err)) {
        setConflictDetail(resolveApiErrorMessage(err, 'Sipariş başka bir kullanıcı tarafından güncellendi.'));
        return;
      }
      toast.error(resolveApiErrorMessage(err, 'Durum güncellenemedi.'));
    },
    onSuccess: async () => {
      toast.success('Sipariş durumu güncellendi.');
      await queryClient.invalidateQueries({ queryKey: ['admin-orders'] });
      if (selectedOrderId) await queryClient.invalidateQueries({ queryKey: ['admin-order-detail', selectedOrderId] });
    },
  });

  return (
    <div className="space-y-8">

      {/* ── Header ── */}
      <div>
        <h1 className="text-[22px] font-semibold text-[var(--primary-800)]">Sipariş Yönetimi</h1>
        <p className="mt-1 text-sm text-[var(--neutral-600)]">Tüm siparişleri izleyin, durumlarını güncelleyin.</p>
      </div>

      {/* ── KPIs ── */}
      <div className="grid grid-cols-2 gap-6 sm:grid-cols-4">
        {[
          { label: 'Toplam', value: kpis.total, icon: ClipboardList },
          { label: 'Yeni', value: kpis.newCount, icon: Clock },
          { label: 'Hazırlık', value: kpis.preparingCount, icon: PackageCheck },
          { label: 'Teslim', value: kpis.deliveredCount, icon: CheckCircle2 },
        ].map(({ label, value, icon: Icon }) => (
          <div key={label}>
            <p className="text-[11px] font-semibold uppercase tracking-[0.25em] text-[var(--neutral-500)]">{label}</p>
            <div className="mt-1 flex items-end gap-2">
              <span className="text-2xl font-semibold text-[var(--primary-800)]">{value}</span>
              <Icon className="mb-1 h-4 w-4 text-[var(--neutral-400)]" />
            </div>
          </div>
        ))}
      </div>

      {/* ── Toolbar ── */}
      <div className="flex items-center justify-between gap-4 border-b border-[var(--neutral-200)] pb-3">
        <p className="text-sm font-medium text-[var(--neutral-700)]">
          {meta?.total ? `${meta.total} sipariş` : ''}
        </p>
        <div className="flex items-center gap-2">
          <span className="text-xs text-[var(--neutral-500)]">Kaynak:</span>
          <select
            value={source}
            onChange={(e) => { setSource(e.target.value); setPage(1); }}
            className="h-8 rounded-[var(--radius-md)] border border-[var(--neutral-200)] bg-white px-2.5 text-xs text-[var(--neutral-700)] outline-none focus:border-[var(--primary-800)]/40"
          >
            <option value="">Tümü</option>
            <option value="POS">POS</option>
            <option value="MOBILE">Mobil</option>
            <option value="WEB">Web</option>
          </select>
        </div>
      </div>

      {/* ── States ── */}
      {isLoading && <Spinner label="Siparişler yükleniyor..." />}
      {isError && !isLoading && (
        <div className="flex items-center gap-2 rounded-[var(--radius-md)] border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          <AlertTriangle className="h-4 w-4" /> Siparişler yüklenemedi.
        </div>
      )}

      {/* ── Table ── */}
      {!isLoading && !isError && orders.length === 0 && (
        <p className="py-10 text-center text-sm text-[var(--neutral-500)]">Sipariş bulunamadı.</p>
      )}

      {!isLoading && !isError && orders.length > 0 && (
        <div className="overflow-x-auto">
          <table className="min-w-full text-sm">
            <thead>
              <tr className="border-b border-[var(--neutral-200)]">
                {['Sipariş', 'Müşteri', 'Tutar', 'Durum', 'Kaynak', 'Tarih'].map((h) => (
                  <th key={h} className={`pb-3 pr-6 text-left text-[11px] font-semibold uppercase tracking-[0.25em] text-[var(--neutral-500)] ${h === 'Tutar' ? 'text-right' : ''}`}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--neutral-100)]">
              {orders.map((order) => (
                <tr
                  key={order.id}
                  onClick={() => setSelectedOrderId(order.id)}
                  className="cursor-pointer transition-colors hover:bg-[var(--neutral-50)]"
                >
                  <td className="py-3 pr-6 font-semibold text-[var(--primary-800)]">#{order.id}</td>
                  <td className="py-3 pr-6 text-[var(--neutral-600)]">#{order.customerId}</td>
                  <td className="py-3 pr-6 text-right font-semibold text-[var(--primary-800)]">{formatPrice(order.totalAmountCents)}</td>
                  <td className="py-3 pr-6"><StatusBadge status={order.statusKey} /></td>
                  <td className="py-3 pr-6"><SourceBadge source={order.source} /></td>
                  <td className="py-3 text-[var(--neutral-500)]">
                    {new Date(order.createdAt).toLocaleString('tr-TR', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* ── Pagination ── */}
      {meta && meta.totalPages > 1 && (
        <div className="flex items-center justify-between border-t border-[var(--neutral-200)] pt-4">
          <p className="text-xs text-[var(--neutral-500)]">Sayfa {meta.page} / {meta.totalPages}</p>
          <div className="flex items-center gap-1">
            <button type="button" onClick={() => setPage((p) => Math.max(1, p - 1))} disabled={meta.page <= 1}
              className="inline-flex h-8 w-8 items-center justify-center rounded-[var(--radius-md)] border border-[var(--neutral-200)] bg-white text-[var(--neutral-700)] hover:bg-[var(--neutral-50)] disabled:opacity-40">
              <ChevronLeft className="h-4 w-4" />
            </button>
            <button type="button" onClick={() => setPage((p) => Math.min(meta.totalPages, p + 1))} disabled={meta.page >= meta.totalPages}
              className="inline-flex h-8 w-8 items-center justify-center rounded-[var(--radius-md)] border border-[var(--neutral-200)] bg-white text-[var(--neutral-700)] hover:bg-[var(--neutral-50)] disabled:opacity-40">
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}

      {/* ── Order Detail Drawer ── */}
      {selectedOrderId !== null && (
        <div className="fixed inset-0 z-50">
          <button type="button" aria-label="Kapat" onClick={() => setSelectedOrderId(null)}
            className="absolute inset-0 bg-black/30 backdrop-blur-sm" />
          <aside className="absolute right-0 top-0 h-full w-full max-w-lg flex flex-col bg-white shadow-2xl">
            <div className="flex items-center justify-between px-6 py-4 border-b border-[var(--neutral-200)]">
              <div>
                <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[var(--neutral-500)]">Sipariş Detayı</p>
                <h3 className="mt-0.5 text-lg font-semibold text-[var(--primary-800)]">#{selectedOrderId}</h3>
              </div>
              <button type="button" onClick={() => setSelectedOrderId(null)}
                className="inline-flex h-8 w-8 items-center justify-center rounded-[var(--radius-md)] border border-[var(--neutral-200)] text-[var(--neutral-600)] hover:bg-[var(--neutral-50)]">
                <X className="h-4 w-4" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto px-6 py-6 space-y-6">
              {(isDetailLoading || isPaymentsLoading) && <Spinner label="Yükleniyor..." />}
              {(isDetailError || isPaymentsError) && (
                <p className="text-sm text-red-600">Detay yüklenemedi.</p>
              )}

              {!isDetailLoading && !isDetailError && orderDetail && (
                <>
                  {/* Summary */}
                  <div>
                    <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[var(--neutral-500)] mb-3">Özet</p>
                    <div className="grid grid-cols-2 gap-y-3 gap-x-6 text-sm">
                      {[
                        { l: 'Müşteri', v: `#${orderDetail.customerId}` },
                        { l: 'Tarih', v: formatDate(orderDetail.createdAt) },
                        { l: 'Toplam', v: formatPrice(orderDetail.totalAmountCents) },
                        { l: 'Kaynak', v: orderDetail.source },
                      ].map(({ l, v }) => (
                        <div key={l}>
                          <p className="text-[11px] text-[var(--neutral-500)]">{l}</p>
                          <p className="mt-0.5 font-semibold text-[var(--primary-800)]">{v}</p>
                        </div>
                      ))}
                    </div>
                    {orderDetail.notes && (
                      <div className="mt-4 pt-4 border-t border-[var(--neutral-200)]">
                        <p className="text-[11px] text-[var(--neutral-500)]">Not</p>
                        <p className="mt-1 text-sm text-[var(--neutral-700)]">{orderDetail.notes}</p>
                      </div>
                    )}
                  </div>

                  {/* Status */}
                  <div>
                    <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[var(--neutral-500)] mb-3">Durum Güncelle</p>
                    <div className="flex items-center gap-3">
                      <StatusBadge status={orderDetail.statusKey} />
                      <select
                        value={orderDetail.statusKey}
                        onChange={(e) => updateStatus.mutate(e.target.value)}
                        disabled={updateStatus.isPending || isStatusesLoading || isStatusesError || !statuses?.length}
                        className="h-9 flex-1 rounded-[var(--radius-md)] border border-[var(--neutral-200)] bg-white px-3 text-sm text-[var(--primary-800)] outline-none focus:border-[var(--primary-800)]/40 disabled:opacity-60"
                      >
                        {(statuses ?? []).slice().sort((a, b) => a.orderIndex - b.orderIndex).map((s) => (
                          <option key={s.id} value={s.key}>{s.label}</option>
                        ))}
                      </select>
                      {updateStatus.isPending && <RefreshCw className="h-4 w-4 animate-spin text-[var(--neutral-400)]" />}
                    </div>
                  </div>

                  {/* Items */}
                  <div>
                    <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[var(--neutral-500)] mb-3">
                      Ürünler ({orderDetail.items.length})
                    </p>
                    <div className="divide-y divide-[var(--neutral-100)]">
                      {orderDetail.items.length === 0 ? (
                        <p className="text-sm text-[var(--neutral-500)]">Ürün satırı yok.</p>
                      ) : orderDetail.items.map((item) => (
                        <div key={item.id} className="flex items-center justify-between py-2.5">
                          <div className="flex items-center gap-3">
                            <div className="h-7 w-7 rounded-[var(--radius-sm)] border border-[var(--neutral-200)] bg-[var(--neutral-50)] flex items-center justify-center flex-shrink-0">
                              <Package className="h-3.5 w-3.5 text-[var(--neutral-400)]" />
                            </div>
                            <div>
                              <p className="text-sm font-semibold text-[var(--primary-800)]">
                                {item.productName ?? `Ürün #${item.productId}`}
                              </p>
                              <p className="text-[11px] text-[var(--neutral-500)]">
                                {item.quantity} × {formatPrice(item.unitPriceCents)}
                              </p>
                            </div>
                          </div>
                          <p className="text-sm font-semibold text-[var(--primary-800)]">{formatPrice(item.totalAmountCents)}</p>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* Payments */}
                  {!isPaymentsLoading && (
                    <div>
                      <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[var(--neutral-500)] mb-3">Ödemeler</p>
                      {!payments || payments.length === 0 ? (
                        <p className="text-sm text-[var(--neutral-500)]">Ödeme kaydı yok.</p>
                      ) : (
                        <div className="divide-y divide-[var(--neutral-100)]">
                          {payments.map((p) => (
                            <div key={p.id} className="flex items-center justify-between py-2.5">
                              <div>
                                <p className="text-sm font-semibold text-[var(--primary-800)]">{p.method}</p>
                                <p className="text-[11px] text-[var(--neutral-500)]">{formatDate(p.createdAt)}</p>
                              </div>
                              <p className="text-sm font-semibold text-[var(--primary-800)]">{formatPrice(p.amountCents)}</p>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  )}
                </>
              )}
            </div>
          </aside>
        </div>
      )}

      <ConflictResolutionModal
        isOpen={Boolean(conflictDetail)}
        detail={conflictDetail ?? undefined}
        onClose={() => setConflictDetail(null)}
        onRefresh={() => {
          setConflictDetail(null);
          void queryClient.invalidateQueries({ queryKey: ['admin-orders'] });
          if (selectedOrderId) {
            void queryClient.invalidateQueries({ queryKey: ['admin-order-detail', selectedOrderId] });
            void queryClient.invalidateQueries({ queryKey: ['admin-order-payments', selectedOrderId] });
          }
        }}
      />
    </div>
  );
}

'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import {
  AlertTriangle,
  ArrowUpRight,
  ClipboardList,
  CreditCard,
  Package,
  RefreshCcw,
  ShoppingBag,
  TrendingUp,
  Users,
  Activity,
  CheckCircle2,
  Clock,
  XCircle,
  ChevronRight,
  Zap,
} from 'lucide-react';

import Spinner from '@/components/common/Spinner';
import api from '@/services/api';
import { formatPrice } from '@/lib/format';
import { useAppSelector } from '@/store';

/* ─── Types ─────────────────────────────────────────────── */

interface DashboardSummary {
  activeProducts: number;
  lowStockProducts: number;
  ordersTotal: number;
  ordersToday: number;
  revenueTodayCents: number;
}

interface DashboardReportsSummary {
  range: { from: string; to: string; days: number };
  ordersCount: number;
  revenueCents: number;
  averageOrderValueCents: number;
  topProducts: Array<{
    productId: number;
    name: string;
    quantity: number;
    revenueCents: number;
  }>;
}

interface CustomerListResponse {
  data: Array<{ id: number; name: string; phone: string }>;
  meta: { total: number };
}

interface OrderListResponse {
  data: Array<{
    id: number;
    customerId: number;
    totalAmountCents: number;
    statusKey: string;
    source: string;
    createdAt: string;
  }>;
  meta: { total: number };
}

interface ReturnRequest { id: number; orderId: number; status: string; requestedAt: string; }
interface OutboxMetrics { totalCount: number; failedCount: number; deadLetterCount: number; retryCount: number; pendingCount: number; }
interface AuditLogRow { id: number; actionType: string; }

/* ─── Helpers ─────────────────────────────────────────────── */

const statusMeta: Record<string, { label: string; color: string; icon: typeof CheckCircle2 }> = {
  PENDING: { label: 'Bekliyor', color: 'bg-amber-100 text-amber-700', icon: Clock },
  CONFIRMED: { label: 'Onaylandı', color: 'bg-blue-100 text-blue-700', icon: CheckCircle2 },
  CANCELLED: { label: 'İptal', color: 'bg-red-100 text-red-700', icon: XCircle },
  COMPLETED: { label: 'Tamamlandı', color: 'bg-green-100 text-green-700', icon: CheckCircle2 },
  PROCESSING: { label: 'İşleniyor', color: 'bg-violet-100 text-violet-700', icon: Activity },
};

function StatusBadge({ status }: { status: string }) {
  const meta = statusMeta[status?.toUpperCase()] ?? { label: status, color: 'bg-gray-100 text-gray-600', icon: Clock };
  const Icon = meta.icon;
  return (
    <span className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] font-medium ${meta.color}`}>
      <Icon className="h-3 w-3" />
      {meta.label}
    </span>
  );
}

function SourceBadge({ source }: { source: string }) {
  const map: Record<string, string> = { POS: 'POS', ONLINE: 'Online', MANUAL: 'Manuel' };
  return (
    <span className="inline-flex items-center rounded-md border border-gray-200 bg-gray-50 px-2 py-0.5 text-[11px] font-medium text-gray-600">
      {map[source] ?? source}
    </span>
  );
}

/* ─── KPI Card ─────────────────────────────────────────────── */

interface StatCardProps {
  title: string;
  value: string;
  note: string;
  icon: React.ComponentType<{ className?: string }>;
  accentClass: string; // Tailwind border-l color class
  trend?: 'up' | 'down' | 'neutral';
}

function StatCard({ title, value, note, icon: Icon, accentClass, trend }: StatCardProps) {
  return (
    <div className={`relative bg-white rounded-xl border border-gray-200 px-5 py-5 shadow-sm hover:shadow-md transition-shadow overflow-hidden border-l-4 ${accentClass}`}>
      <div className="flex items-start justify-between gap-2">
        <div className="flex-1 min-w-0">
          <p className="text-[12px] font-medium text-gray-500">{title}</p>
          <p className="mt-2 text-2xl font-bold text-gray-900 tracking-tight truncate">{value}</p>
          <p className="mt-1 text-[11px] text-gray-400">{note}</p>
        </div>
        <div className="h-10 w-10 rounded-xl bg-gray-50 border border-gray-100 flex items-center justify-center flex-shrink-0">
          <Icon className="h-5 w-5 text-gray-500" />
        </div>
      </div>
    </div>
  );
}

/* ─── Section Header ─────────────────────────────────────────── */

function SectionHeader({ title, subtitle, action }: { title: string; subtitle?: string; action?: React.ReactNode }) {
  return (
    <div className="flex items-center justify-between mb-4">
      <div>
        <h2 className="text-base font-semibold text-gray-900">{title}</h2>
        {subtitle && <p className="mt-0.5 text-[12px] text-gray-500">{subtitle}</p>}
      </div>
      {action}
    </div>
  );
}

/* ─── Quick Link Card ─────────────────────────────────────────── */

function QuickLinkCard({ label, href, icon: Icon, description }: { label: string; href: string; icon: React.ComponentType<{ className?: string }>; description: string }) {
  return (
    <Link
      href={href}
      className="group flex items-center gap-4 rounded-xl border border-gray-200 bg-white px-4 py-4 shadow-sm hover:shadow-md hover:border-gray-300 transition-all"
    >
      <div className="h-10 w-10 rounded-lg bg-gray-50 border border-gray-100 flex items-center justify-center flex-shrink-0 group-hover:bg-gray-100 transition-colors">
        <Icon className="h-5 w-5 text-gray-600" />
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-[13px] font-semibold text-gray-800 leading-none">{label}</p>
        <p className="mt-1 text-[11px] text-gray-500 truncate">{description}</p>
      </div>
      <ArrowUpRight className="h-4 w-4 text-gray-400 flex-shrink-0 group-hover:text-gray-600 transition-colors" />
    </Link>
  );
}

/* ─── Main Component ─────────────────────────────────────────── */

export default function AdminOverviewPage() {
  const pathname = usePathname();
  const user = useAppSelector((s) => s.user.user);
  const basePath = pathname.startsWith('/platform') ? '/platform' : '/admin';
  const isSuperAdmin = user?.role === 'SUPER_ADMIN';

  /* Queries */
  const summaryQ = useQuery<DashboardSummary>({
    queryKey: ['admin-dash-summary'],
    queryFn: async () => (await api.get<DashboardSummary>('/dashboard/summary')).data,
  });

  const reportsQ = useQuery<DashboardReportsSummary>({
    queryKey: ['admin-dash-reports'],
    queryFn: async () => (await api.get<DashboardReportsSummary>('/dashboard/reports/summary')).data,
  });

  const customersQ = useQuery<CustomerListResponse>({
    queryKey: ['admin-dash-customers'],
    queryFn: async () => (await api.get<CustomerListResponse>('/customers?page=1&pageSize=1')).data,
  });

  const returnsQ = useQuery<ReturnRequest[]>({
    queryKey: ['admin-dash-returns'],
    queryFn: async () => (await api.get<ReturnRequest[]>('/platform/return-requests?status=PENDING')).data,
  });

  const ordersQ = useQuery<OrderListResponse>({
    queryKey: ['admin-dash-orders'],
    queryFn: async () => (await api.get<OrderListResponse>('/platform/orders?page=1&pageSize=8')).data,
  });

  const outboxQ = useQuery<OutboxMetrics>({
    queryKey: ['admin-dash-outbox'],
    queryFn: async () => (await api.get<OutboxMetrics>('/platform/outbox/metrics')).data,
  });

  const auditQ = useQuery<{ data: AuditLogRow[] }>({
    queryKey: ['admin-dash-audit'],
    queryFn: async () => (await api.get<{ data: AuditLogRow[] }>('/platform/audit/logs?page=1&pageSize=20')).data,
  });

  const isLoading = summaryQ.isLoading || reportsQ.isLoading || ordersQ.isLoading || customersQ.isLoading;
  const isError = summaryQ.isError || reportsQ.isError || ordersQ.isError || customersQ.isError;

  const summary = summaryQ.data;
  const reports = reportsQ.data;
  const orders = ordersQ.data?.data ?? [];
  const topProducts = reports?.topProducts ?? [];
  const customerTotal = customersQ.data?.meta?.total ?? 0;
  const pendingReturns = returnsQ.data?.length ?? 0;

  /* Risk Score */
  const riskScore = useMemo(() => {
    const m = outboxQ.data;
    if (!m) return 0;
    const total = Math.max(m.totalCount, 1);
    const failed = ((m.failedCount + m.deadLetterCount) / total) * 100;
    const retry = (m.retryCount / total) * 100;
    const overrides = (auditQ.data?.data ?? []).filter((r) => {
      const a = String(r.actionType ?? '').toUpperCase();
      return a.includes('FORCE') || a.includes('OVERRIDE');
    }).length;
    return Math.min(100, Math.round(failed * 0.6 + retry * 0.2 + overrides * 2));
  }, [outboxQ.data, auditQ.data]);

  /* KPI Cards */
  const statCards: StatCardProps[] = useMemo(() => [
    {
      title: 'Bugün Sipariş',
      value: summary ? String(summary.ordersToday) : '—',
      note: 'Son 24 saat',
      icon: ClipboardList,
      accentClass: 'border-l-blue-500',
    },
    {
      title: 'Bugün Ciro',
      value: summary ? formatPrice(summary.revenueTodayCents) : '—',
      note: 'Tahsil edilen',
      icon: CreditCard,
      accentClass: 'border-l-emerald-500',
    },
    {
      title: 'Toplam Sipariş',
      value: summary ? String(summary.ordersTotal) : '—',
      note: 'Tüm zamanlar',
      icon: ShoppingBag,
      accentClass: 'border-l-violet-500',
    },
    {
      title: '30 Gün Ciro',
      value: reports ? formatPrice(reports.revenueCents) : '—',
      note: `${reports?.ordersCount ?? 0} sipariş`,
      icon: TrendingUp,
      accentClass: 'border-l-cyan-500',
    },
    {
      title: 'Aktif Ürün',
      value: summary ? String(summary.activeProducts) : '—',
      note: 'Yayında',
      icon: Package,
      accentClass: 'border-l-amber-500',
    },
    {
      title: 'Düşük Stok',
      value: summary ? String(summary.lowStockProducts) : '—',
      note: '≤ 5 adet',
      icon: AlertTriangle,
      accentClass: summary?.lowStockProducts ? 'border-l-red-500' : 'border-l-gray-300',
    },
    {
      title: 'Kayıtlı Müşteri',
      value: String(customerTotal),
      note: 'Toplam havuz',
      icon: Users,
      accentClass: 'border-l-teal-500',
    },
    {
      title: 'Bekleyen İade',
      value: String(pendingReturns),
      note: 'Onay bekliyor',
      icon: RefreshCcw,
      accentClass: pendingReturns > 0 ? 'border-l-orange-500' : 'border-l-gray-300',
    },
  ], [summary, reports, customerTotal, pendingReturns]);

  /* Quick Links */
  const quickLinks = useMemo(() => (isSuperAdmin ? [
    { label: 'Kullanıcı Yönetimi', href: `${basePath}/users`, icon: Users, description: 'Admin ve satıcı hesaplarını yönet' },
    { label: 'Satıcı Operasyonu', href: `${basePath}/sellers`, icon: Zap, description: 'Satıcı onayları ve operasyon takibi' },
    { label: 'Başvuru Havuzu', href: `${basePath}/sellers/applications`, icon: Package, description: 'Bekleyen satıcı başvuruları' },
    { label: 'Plan Yönetimi', href: `${basePath}/plans`, icon: CreditCard, description: 'Abonelik planları ve limitler' },
    { label: 'Finans Raporları', href: `${basePath}/finance`, icon: TrendingUp, description: 'Gelir, payout ve iade verileri' },
    { label: 'Risk Kontrolü', href: `${basePath}/risk-control`, icon: AlertTriangle, description: 'Outbox, audit ve risk metrikleri' },
  ] : [
    { label: 'Sipariş Takibi', href: `${basePath}/orders`, icon: ClipboardList, description: 'Tüm siparişleri izle ve yönet' },
    { label: 'Ürün Yönetimi', href: `${basePath}/products`, icon: Package, description: 'Stok, fiyat ve ürün bilgileri' },
    { label: 'Müşteri Paneli', href: `${basePath}/customers`, icon: Users, description: 'Müşteri listesi ve bakiyeler' },
    { label: 'Ödeme Operasyonu', href: `${basePath}/payments`, icon: CreditCard, description: 'Ödeme kayıtları ve tahsilatlar' },
    { label: 'Finans Raporları', href: `${basePath}/finance`, icon: TrendingUp, description: 'Ciro ve iade raporları' },
    { label: 'İade Yönetimi', href: `${basePath}/finance/refunds`, icon: RefreshCcw, description: 'Bekleyen iade talepleri' },
  ]), [basePath, isSuperAdmin]);

  const isNewStore = Boolean(summary && summary.ordersTotal === 0 && summary.activeProducts === 0);

  /* Render */
  return (
    <div className="space-y-8">

      {/* ── Page Header ── */}
      <div className="flex items-start justify-between gap-4 flex-wrap">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span className="inline-flex items-center gap-1 text-[11px] font-semibold text-emerald-600">
              <span className="h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" />
              Canlı
            </span>
            {riskScore > 30 && (
              <span className="inline-flex items-center gap-1 text-[11px] font-semibold text-red-600">
                <AlertTriangle className="h-3 w-3" />
                Risk: {riskScore}
              </span>
            )}
          </div>
          <h1 className="text-[22px] font-semibold text-[var(--primary-800)]">
            {isSuperAdmin ? 'Platform Dashboard' : 'Admin Dashboard'}
          </h1>
          <p className="mt-1 text-sm text-[var(--neutral-600)]">
            {isSuperAdmin
              ? 'Satıcı, kullanıcı ve operasyon akışını tek merkezden izle.'
              : 'Sipariş, stok, müşteri ve iade operasyonunu izle.'}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Link href={`${basePath}/reports`}
            className="inline-flex items-center gap-1.5 text-xs font-semibold text-[var(--neutral-600)] hover:text-[var(--primary-800)] transition">
            <TrendingUp className="h-4 w-4" />Raporlar
          </Link>
          <Link href={`${basePath}/orders`}
            className="inline-flex items-center gap-1.5 text-xs font-semibold text-[var(--primary-800)] hover:underline underline-offset-2">
            <ClipboardList className="h-4 w-4" />Siparisler
          </Link>
        </div>
      </div>

      {/* ── Loading / Error ── */}
      {isLoading && <Spinner label="Veriler yükleniyor..." />}

      {isError && (
        <div className="flex items-center gap-2 rounded-[var(--radius-md)] border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          <AlertTriangle className="h-4 w-4 flex-shrink-0" />
          Dashboard verileri yüklenemedi.
        </div>
      )}

      {!isLoading && !isError && (
        <>
          {/* ── New Store Guide ── */}
          {isNewStore && (
            <div className="rounded-xl border border-amber-200 bg-gradient-to-br from-amber-50 to-orange-50 px-5 py-5 shadow-sm">
              <div className="flex items-center gap-2 mb-3">
                <Zap className="h-4 w-4 text-amber-600" />
                <span className="text-[12px] font-bold uppercase tracking-wide text-amber-700">
                  Hızlı Başlangıç
                </span>
              </div>
              <h2 className="text-lg font-semibold text-gray-900 mb-1">Panel hazır, sıra sizde!</h2>
              <p className="text-sm text-gray-600 mb-4">
                Henüz sipariş ve ürün verisi yok. Aşağıdaki adımlarla başlayın.
              </p>
              <div className="grid gap-2 sm:grid-cols-3">
                {(isSuperAdmin
                  ? [
                    { label: 'Kullanıcı Ekle', href: `${basePath}/users` },
                    { label: 'Satıcıları Yönet', href: `${basePath}/sellers` },
                    { label: 'Planları Hazırla', href: `${basePath}/plans` },
                  ]
                  : [
                    { label: 'İlk Ürünü Ekle', href: `${basePath}/products` },
                    { label: 'Kategori Oluştur', href: `${basePath}/categories` },
                    { label: 'Siparişleri İzle', href: `${basePath}/orders` },
                  ]
                ).map((cta) => (
                  <Link
