'use client';

import { useMemo, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import toast from 'react-hot-toast';

import api from '@/services/api';

type PlanInterval = 'MONTHLY' | 'YEARLY';

type PlanRow = {
  id: number;
  name: string;
  interval: PlanInterval;
  priceCents: number;
  currency: string;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
};

type PaginationMeta = {
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
};

type PaginatedPlans = {
  data: PlanRow[];
  meta: PaginationMeta;
};

const resolveApiErrorMessage = (error: unknown, fallback: string) => {
  if (!error || typeof error !== 'object') return fallback;
  if (!('response' in error)) return fallback;
  const response = (error as { response?: unknown }).response;
  if (!response || typeof response !== 'object') return fallback;
  if (!('data' in response)) return fallback;
  const data = (response as { data?: unknown }).data;
  if (!data || typeof data !== 'object') return fallback;
  if (!('message' in data)) return fallback;
  const message = (data as { message?: unknown }).message;
  if (Array.isArray(message)) return message.map(String).join(', ');
  if (typeof message === 'string') return message;
  return fallback;
};

const intervalLabel: Record<PlanInterval, string> = {
  MONTHLY: 'Aylık',
  YEARLY: 'Yıllık',
};

export default function AdminPlansPage() {
  const queryClient = useQueryClient();

  const [interval, setInterval] = useState<'' | PlanInterval>('');
  const [activeFilter, setActiveFilter] = useState<'' | 'true' | 'false'>('');
  const [page, setPage] = useState(1);
  const [pageSize] = useState(20);

  const [createName, setCreateName] = useState('');
  const [createInterval, setCreateInterval] = useState<PlanInterval>('MONTHLY');
  const [createPriceCents, setCreatePriceCents] = useState<number>(0);
  const [createCurrency, setCreateCurrency] = useState('TRY');

  const {
    data: plansPayload,
    isLoading,
    isError,
  } = useQuery<PaginatedPlans>({
    queryKey: ['admin-plans', { interval, activeFilter, page, pageSize }],
    queryFn: async () => {
      const res = await api.get<PaginatedPlans>('/platform/plans', {
        params: {
          interval: interval || undefined,
          isActive: activeFilter || undefined,
          page,
          pageSize,
        },
      });
      return res.data;
    },
  });

  const plans = plansPayload?.data ?? [];
  const meta = plansPayload?.meta;

  const createPlanMutation = useMutation({
    mutationFn: async () => {
      await api.post('/platform/plans', {
        name: createName.trim(),
        interval: createInterval,
        priceCents: Number(createPriceCents),
        currency: createCurrency.trim() || 'TRY',
        isActive: true,
      });
    },
    onError: (error: unknown) => {
      toast.error(resolveApiErrorMessage(error, 'Plan oluşturulamadı.'));
    },
    onSuccess: async () => {
      toast.success('Plan oluşturuldu.');
      setCreateName('');
      setCreatePriceCents(0);
      await queryClient.invalidateQueries({ queryKey: ['admin-plans'] });
    },
  });

  const toggleActiveMutation = useMutation({
    mutationFn: async (payload: { id: number; isActive: boolean }) => {
      await api.patch(`/platform/plans/${payload.id}`, { isActive: payload.isActive });
    },
    onError: (error: unknown) => {
      toast.error(resolveApiErrorMessage(error, 'Durum güncellenemedi.'));
    },
    onSuccess: async () => {
      toast.success('Durum güncellendi.');
      await queryClient.invalidateQueries({ queryKey: ['admin-plans'] });
    },
  });

  const kpis = useMemo(() => {
    const total = meta?.total ?? plans.length;
    const activeCount = plans.filter((p) => p.isActive).length;
    return { total, activeCount };
  }, [plans, meta]);

  const canCreate = createName.trim().length > 0 && Number.isFinite(createPriceCents) && createPriceCents >= 0;

  return (
    <div className="space-y-6">
      <section className="border-b border-[var(--neutral-200)] pb-6">
        <div className="flex flex-wrap items-end justify-between gap-4">
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[var(--neutral-500)]">
              Platform
            </p>
            <h1 className="mt-2 text-2xl font-serif text-[var(--primary-800)] md:text-3xl lg:text-4xl">
              Planlar
            </h1>
            <p className="mt-2 text-sm text-[var(--neutral-600)]">
              Aylık ve yıllık planları yönetin.
            </p>
          </div>
          <div className="rounded-full border border-[var(--neutral-200)] bg-white px-4 py-2 text-[11px] font-semibold uppercase tracking-[0.25em] text-[var(--primary-800)]">
            Aktif: {kpis.activeCount} / {kpis.total}
          </div>
        </div>
      </section>

      <section className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white">
        <div className="flex flex-col gap-3 border-b border-[var(--neutral-200)] px-4 py-4 md:flex-row md:items-center md:justify-between md:px-6">
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[var(--neutral-500)]">
              Filtre
            </p>
            <p className="mt-1 text-sm text-[var(--neutral-600)]">
              Toplam: <span className="font-semibold text-[var(--primary-800)]">{meta?.total ?? plans.length}</span>
            </p>
          </div>
          <div className="flex w-full flex-col gap-2 md:w-auto md:flex-row md:items-center">
            <select
              value={interval}
              onChange={(e) => {
                setInterval(e.target.value as '' | PlanInterval);
                setPage(1);
              }}
              className="h-11 w-full rounded-[var(--radius-lg)] border border-[var(--neutral-200)] bg-white px-3 text-xs font-semibold uppercase tracking-[0.2em] text-[var(--primary-800)] outline-none transition focus:border-[var(--primary-800)]/30 md:w-40"
            >
              <option value="">Tümü</option>
              <option value="MONTHLY">Aylık</option>
              <option value="YEARLY">Yıllık</option>
            </select>

            <select
              value={activeFilter}
              onChange={(e) => {
                setActiveFilter(e.target.value as '' | 'true' | 'false');
                setPage(1);
              }}
              className="h-11 w-full rounded-[var(--radius-lg)] border border-[var(--neutral-200)] bg-white px-3 text-xs font-semibold uppercase tracking-[0.2em] text-[var(--primary-800)] outline-none transition focus:border-[var(--primary-800)]/30 md:w-40"
            >
              <option value="">Tümü</option>
              <option value="true">Aktif</option>
              <option value="false">Pasif</option>
            </select>
          </div>
        </div>

        {isLoading && (
          <div className="px-4 py-6 text-sm text-[var(--neutral-600)] md:px-6">Planlar yükleniyor...</div>
        )}

        {isError && !isLoading && (
          <div className="px-4 py-6 text-sm text-[var(--neutral-600)] md:px-6">Planlar alınamadı.</div>
        )}

        {!isLoading && !isError && (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[720px] border-collapse">
              <thead>
                <tr className="border-b border-[var(--neutral-200)] text-left text-[10px] font-semibold uppercase tracking-[0.25em] text-[var(--neutral-500)]">
                  <th className="px-4 py-3 md:px-6">Plan</th>
                  <th className="px-4 py-3 md:px-6">Periyot</th>
                  <th className="px-4 py-3 md:px-6">Fiyat</th>
                  <th className="px-4 py-3 md:px-6">Durum</th>
                  <th className="px-4 py-3 md:px-6"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--neutral-200)]">
                {plans.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="px-4 py-10 text-sm text-[var(--neutral-600)] md:px-6">
                      Plan bulunamadı.
                    </td>
                  </tr>
                ) : (
                  plans.map((p) => (
                    <tr key={p.id} className="text-sm text-[var(--primary-800)]">
                      <td className="px-4 py-4 md:px-6">
                        <div className="min-w-0">
                          <p className="truncate font-semibold">{p.name}</p>
                          <p className="mt-1 text-xs text-[var(--neutral-600)]">ID: {p.id}</p>
                        </div>
                      </td>
                      <td className="px-4 py-4 md:px-6">
                        <span className="inline-flex items-center rounded-full border border-[var(--neutral-200)] bg-white px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.2em] text-[var(--primary-800)]/70">
                          {intervalLabel[p.interval]}
                        </span>
                      </td>
                      <td className="px-4 py-4 md:px-6 font-semibold">
                        {(p.priceCents / 100).toFixed(2)} {p.currency}
                      </td>
                      <td className="px-4 py-4 md:px-6">
                        <span
                          className={`inline-flex items-center rounded-full border px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.2em] ${
                            p.isActive
                              ? 'border-[var(--neutral-200)] bg-white text-[var(--primary-800)]/70'
                              : 'border-[var(--neutral-200)] bg-[var(--neutral-50)] text-[var(--primary-800)]'
                          }`}
                        >
                          {p.isActive ? 'aktif' : 'pasif'}
                        </span>
                      </td>
                      <td className="px-4 py-4 text-right md:px-6">
                        <button
                          type="button"
                          disabled={toggleActiveMutation.isPending}
                          onClick={() => toggleActiveMutation.mutate({ id: p.id, isActive: !p.isActive })}
                          className="inline-flex h-10 items-center justify-center rounded-full border border-[var(--neutral-200)] bg-white px-4 text-[11px] font-semibold uppercase tracking-[0.25em] text-[var(--primary-800)] transition hover:bg-[var(--neutral-50)] disabled:opacity-60"
                        >
                          {p.isActive ? 'Pasife al' : 'Aktifleştir'}
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        )}

        {!isLoading && !isError && meta && meta.totalPages > 1 && (
          <div className="flex flex-wrap items-center justify-between gap-3 border-t border-[var(--neutral-200)] px-4 py-4 text-xs text-[var(--neutral-600)] md:px-6">
            <span className="text-[11px] font-semibold uppercase tracking-[0.25em] text-[var(--primary-800)]/60">
              Sayfa {meta.page} / {meta.totalPages}
            </span>
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={meta.page <= 1}
                className="inline-flex h-11 items-center gap-2 rounded-[var(--radius-md)] border border-[var(--neutral-200)] bg-white px-4 text-xs font-semibold uppercase tracking-[0.2em] text-[var(--primary-800)] shadow-sm disabled:cursor-not-allowed disabled:opacity-50"
              >
                Önceki
              </button>
              <button
                type="button"
                onClick={() => setPage((p) => Math.min(meta.totalPages, p + 1))}
                disabled={meta.page >= meta.totalPages}
                className="inline-flex h-11 items-center gap-2 rounded-[var(--radius-md)] border border-[var(--primary-800)] bg-[var(--primary-800)] px-4 text-xs font-semibold uppercase tracking-[0.2em] text-white shadow-sm disabled:cursor-not-allowed disabled:opacity-50"
              >
                Sonraki
              </button>
            </div>
          </div>
        )}
      </section>

      <section className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-4 py-5 md:px-6">
        <div className="flex flex-wrap items-end justify-between gap-4">
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[var(--neutral-500)]">
              Yeni plan
            </p>
            <h2 className="mt-2 text-2xl font-serif text-[var(--primary-800)]">Plan oluştur</h2>
            <p className="mt-2 text-sm text-[var(--neutral-600)]">
              Aylık veya yıllık plan tanımlayın.
            </p>
          </div>
        </div>

        <div className="mt-6 grid gap-3 md:grid-cols-4">
          <input
            value={createName}
            onChange={(e) => setCreateName(e.target.value)}
            placeholder="Plan adı"
            className="h-11 rounded-[var(--radius-lg)] border border-[var(--neutral-200)] bg-white px-4 text-sm text-[var(--primary-900)] outline-none transition placeholder:text-[var(--neutral-500)] focus:border-[var(--primary-800)]/30"
          />

          <select
            value={createInterval}
            onChange={(e) => setCreateInterval(e.target.value as PlanInterval)}
            className="h-11 rounded-[var(--radius-lg)] border border-[var(--neutral-200)] bg-white px-3 text-xs font-semibold uppercase tracking-[0.2em] text-[var(--primary-800)] outline-none transition focus:border-[var(--primary-800)]/30"
          >
            <option value="MONTHLY">Aylık</option>
            <option value="YEARLY">Yıllık</option>
          </select>

          <input
            value={String(createPriceCents)}
            onChange={(e) => setCreatePriceCents(Number(e.target.value))}
            inputMode="numeric"
            type="number"
            min={0}
            placeholder="Fiyat (kuruş)"
            className="h-11 rounded-[var(--radius-lg)] border border-[var(--neutral-200)] bg-white px-4 text-sm text-[var(--primary-900)] outline-none transition placeholder:text-[var(--neutral-500)] focus:border-[var(--primary-800)]/30"
          />

          <input
            value={createCurrency}
            onChange={(e) => setCreateCurrency(e.target.value)}
            placeholder="Para birimi (TRY)"
            className="h-11 rounded-[var(--radius-lg)] border border-[var(--neutral-200)] bg-white px-4 text-sm text-[var(--primary-900)] outline-none transition placeholder:text-[var(--neutral-500)] focus:border-[var(--primary-800)]/30"
          />
        </div>

        <div className="mt-4 flex justify-end">
          <button
            type="button"
            disabled={createPlanMutation.isPending || !canCreate}
            onClick={() => createPlanMutation.mutate()}
            className="inline-flex h-11 items-center justify-center rounded-full border border-[var(--primary-800)] bg-[var(--primary-800)] px-6 text-[11px] font-semibold uppercase tracking-[0.25em] text-white transition hover:opacity-95 disabled:opacity-60"
          >
            Oluştur
          </button>
        </div>
      </section>
    </div>
  );
}

'use client';

import { FormEvent, useMemo, useState } from 'react';
import toast from 'react-hot-toast';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { AlertTriangle, Archive, Download, Pencil, Save, Upload, X } from 'lucide-react';

import Button from '@/components/common/Button';
import Spinner from '@/components/common/Spinner';
import api from '@/services/api';
import { formatPrice } from '@/utils/helpers';

const resolveApiErrorMessage = (error: unknown, fallback: string) => {
  if (!error || typeof error !== 'object') return fallback;
  if (!('response' in error)) return fallback;
  const response = (error as { response?: unknown }).response;
  if (!response || typeof response !== 'object') return fallback;
  if (!('data' in response)) return fallback;
  const data = (response as { data?: unknown }).data;
  if (!data || typeof data !== 'object') return fallback;
  if (!('message' in data)) return fallback;
  const message = (data as { message?: unknown }).message;
  if (Array.isArray(message)) {
    return message.map(String).join(', ');
  }
  if (typeof message === 'string') return message;
  return fallback;
};

type ProductType = 'PHYSICAL' | 'SERVICE' | 'WEIGHT' | 'CUSTOM';

interface CategoryTreeNode {
  id: number;
  name: string;
  slug: string;
  parentId?: number | null;
  orderIndex: number;
  children?: CategoryTreeNode[];
}

interface ProductRow {
  id: number;
  categoryId?: number | null;
  name: string;
  subtitle?: string | null;
  sku?: string | null;
  type: ProductType;
  priceCents: number;
  description?: string | null;
  features?: string[];
  imageUrl?: string | null;
  stock?: number | null;
  tags?: string[];
  isActive: boolean;
  updatedAt?: string;
}

interface PaginationMeta {
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
}

interface PaginatedProducts {
  data: ProductRow[];
  meta: PaginationMeta;
}

interface ProductCsvImportReport {
  totalRows: number;
  created: number;
  updated: number;
  skipped: number;
  errors: Array<{ line: number; message: string }>;
}

const formatType = (type: ProductType) => {
  switch (type) {
    case 'PHYSICAL':
      return 'Fiziksel';
    case 'SERVICE':
      return 'Hizmet';
    case 'WEIGHT':
      return 'Kilo';
    case 'CUSTOM':
      return 'Özel';
    default:
      return type;
  }
};

export default function AdminProductsPage() {
  const queryClient = useQueryClient();

  const [page, setPage] = useState(1);
  const [pageSize] = useState(20);
  const [csvInput, setCsvInput] = useState('');
  const [importReport, setImportReport] = useState<ProductCsvImportReport | null>(null);

  const [createForm, setCreateForm] = useState({
    name: '',
    subtitle: '',
    sku: '',
    categoryId: '',
    type: 'PHYSICAL' as ProductType,
    priceCents: '',
    stock: '',
    imageUrl: '',
    description: '',
    features: '',
  });

  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState({
    name: '',
    subtitle: '',
    sku: '',
    categoryId: '',
    type: 'PHYSICAL' as ProductType,
    priceCents: '',
    stock: '',
    imageUrl: '',
    description: '',
    features: '',
  });

  const parseFeatures = (value: string) =>
    value
      .split(/\r?\n/)
      .map((entry) => entry.trim())
      .filter(Boolean);

  const uploadMutation = useMutation({
    mutationFn: async (file: File) => {
      const formData = new FormData();
      formData.append('file', file);
      const res = await api.post<{ url: string }>(
        '/uploads/product-image',
        formData,
        {
          headers: {
            'Content-Type': 'multipart/form-data',
          },
        },
      );
      return res.data;
    },
    onError: (error: unknown) => {
      toast.error(resolveApiErrorMessage(error, 'Görsel yüklenemedi.'));
    },
  });

  const {
    data: categoriesTree,
    isLoading: categoriesLoading,
    isError: categoriesError,
  } = useQuery<CategoryTreeNode[]>({
    queryKey: ['admin-categories-tree'],
    queryFn: async () => {
      const res = await api.get<CategoryTreeNode[]>('/categories/tree');
      return res.data;
    },
  });

  // Flatten tree for select dropdown with indentation
  const flattenCategories = (tree: CategoryTreeNode[], level = 0): Array<{ id: number; name: string; level: number }> => {
    const result: Array<{ id: number; name: string; level: number }> = [];
    for (const cat of tree) {
      result.push({ id: cat.id, name: cat.name, level });
      if (cat.children) {
        result.push(...flattenCategories(cat.children, level + 1));
      }
    }
    return result;
  };

  const flatCategories = useMemo(() => {
    return flattenCategories(categoriesTree || []);
  }, [categoriesTree]);

  const categoryNameById = useMemo(() => {
    const map = new Map<number, string>();
    const mapFromTree = (tree: CategoryTreeNode[]) => {
      for (const cat of tree) {
        map.set(cat.id, cat.name);
        if (cat.children) {
          mapFromTree(cat.children);
        }
      }
    };
    mapFromTree(categoriesTree || []);
    return map;
  }, [categoriesTree]);

  const {
    data: productsPayload,
    isLoading,
    isError,
  } = useQuery<PaginatedProducts>({
    queryKey: ['admin-products', { page, pageSize }],
    queryFn: async () => {
      const res = await api.get<PaginatedProducts>('/products', {
        params: {
          page,
          pageSize,
        },
      });
      return res.data;
    },
  });

  const products = productsPayload?.data ?? [];
  const meta = productsPayload?.meta;

  const lowStockCount = useMemo(() => {
    if (!products) return 0;
    return products.filter((p) => typeof p.stock === 'number' && p.stock <= 5).length;
  }, [products]);

  const createMutation = useMutation({
    mutationFn: async () => {
      const priceCents = Number(createForm.priceCents);
      const stock = createForm.stock ? Number(createForm.stock) : undefined;
      const parsedCategoryId = createForm.categoryId ? Number(createForm.categoryId) : undefined;
      
      if (!createForm.name.trim()) {
        throw new Error('Ürün adı zorunludur.');
      }
      if (!priceCents || Number.isNaN(priceCents) || priceCents < 0) {
        throw new Error('Fiyat (kuruş) geçerli olmalıdır.');
      }
      if (!parsedCategoryId || Number.isNaN(parsedCategoryId) || parsedCategoryId < 1) {
        throw new Error('Kategori seçimi zorunludur.');
      }

      await api.post('/products', {
        name: createForm.name.trim(),
        subtitle: createForm.subtitle.trim() || undefined,
        sku: createForm.sku.trim() || undefined,
        categoryId: parsedCategoryId,
        type: createForm.type,
        price: String(priceCents),
        description: createForm.description.trim() || undefined,
        features: parseFeatures(createForm.features),
        stock: typeof stock === 'number' && !Number.isNaN(stock) ? stock : undefined,
        imageUrl: createForm.imageUrl.trim() || undefined,
      });
    },
    onSuccess: async () => {
      toast.success('Ürün oluşturuldu.');
      setCreateForm({
        name: '',
        subtitle: '',
        sku: '',
        categoryId: '',
        type: 'PHYSICAL',
        priceCents: '',
        stock: '',
        imageUrl: '',
        description: '',
        features: '',
      });
      await queryClient.invalidateQueries({ queryKey: ['admin-products'] });
    },
    onError: (error: unknown) => {
      toast.error(resolveApiErrorMessage(error, 'Ürün oluşturulamadı.'));
    },
  });

  const updateMutation = useMutation({
    mutationFn: async (productId: number) => {
      const priceCents = editForm.priceCents ? Number(editForm.priceCents) : undefined;
      const stock = editForm.stock ? Number(editForm.stock) : undefined;
      const parsedCategoryId = editForm.categoryId ? Number(editForm.categoryId) : undefined;

      if (!parsedCategoryId || Number.isNaN(parsedCategoryId) || parsedCategoryId < 1) {
        throw new Error('Kategori seçimi zorunludur.');
      }

      await api.patch(`/products/${productId}`, {
        name: editForm.name.trim() || undefined,
        subtitle: editForm.subtitle.trim() || undefined,
        sku: editForm.sku.trim() || undefined,
        categoryId: parsedCategoryId,
        type: editForm.type,
        price:
          typeof priceCents === 'number' && !Number.isNaN(priceCents)
            ? String(priceCents)
            : undefined,
        description: editForm.description.trim() || undefined,
        features: parseFeatures(editForm.features),
        stock:
          typeof stock === 'number' && !Number.isNaN(stock) ? stock : undefined,
        imageUrl: editForm.imageUrl.trim() || undefined,
      });
    },
    onSuccess: async () => {
      toast.success('Ürün güncellendi.');
      setEditingId(null);
      await queryClient.invalidateQueries({ queryKey: ['admin-products'] });
    },
    onError: (error: unknown) => {
      toast.error(resolveApiErrorMessage(error, 'Ürün güncellenemedi.'));
    },
  });

  const archiveMutation = useMutation({
    mutationFn: async (productId: number) => {
      await api.delete(`/products/${productId}`);
    },
    onSuccess: async () => {
      toast.success('Ürün arşivlendi.');
      await queryClient.invalidateQueries({ queryKey: ['admin-products'] });
    },
    onError: (error: unknown) => {
      toast.error(resolveApiErrorMessage(error, 'Ürün arşivlenemedi.'));
    },
  });

  const exportCsvMutation = useMutation({
    mutationFn: async () => {
      const res = await api.get<string>('/products/export/csv', {
        responseType: 'text',
      });
      return res.data;
    },
    onSuccess: (csv) => {
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const url = window.URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = `products-${new Date().toISOString().slice(0, 10)}.csv`;
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      window.URL.revokeObjectURL(url);
      toast.success('Urun CSV indirildi.');
    },
    onError: (error: unknown) => {
      toast.error(resolveApiErrorMessage(error, 'CSV export basarisiz.'));
    },
  });

  const importCsvMutation = useMutation({
    mutationFn: async () => {
      const csv = csvInput.trim();
      if (!csv) {
        throw new Error('CSV metnini girin.');
      }

      const res = await api.post<ProductCsvImportReport>('/products/import/csv', {
        csv,
        upsertBy: 'sku',
      });
      return res.data;
    },
    onSuccess: async (report) => {
      setImportReport(report);
      await queryClient.invalidateQueries({ queryKey: ['admin-products'] });
      if (report.errors.length > 0) {
        toast.error(
          `Import tamamlandi: ${report.created} yeni, ${report.updated} guncel, ${report.errors.length} hata.`,
        );
      } else {
        toast.success(
          `Import tamamlandi: ${report.created} yeni, ${report.updated} guncellendi.`,
        );
      }
    },
    onError: (error: unknown) => {
      toast.error(resolveApiErrorMessage(error, 'CSV import basarisiz.'));
    },
  });

  const beginEdit = (product: ProductRow) => {
    setEditingId(product.id);
    setEditForm({
      name: product.name ?? '',
      subtitle: product.subtitle ?? '',
      sku: product.sku ?? '',
      categoryId:
        product.categoryId === null || product.categoryId === undefined
          ? ''
          : String(product.categoryId),
      type: product.type,
      priceCents: String(product.priceCents ?? ''),
      stock: product.stock === null || product.stock === undefined ? '' : String(product.stock),
      imageUrl: product.imageUrl ?? '',
      description: product.description ?? '',
      features: (product.features ?? []).join('\n'),
    });
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditForm({
      name: '',
      subtitle: '',
      sku: '',
      categoryId: '',
      type: 'PHYSICAL',
      priceCents: '',
      stock: '',
      imageUrl: '',
      description: '',
      features: '',
    });
  };

  const handleCreate = (event: FormEvent) => {
    event.preventDefault();
    createMutation.mutate();
  };

  return (
    <div className="space-y-6">
      <section className="rounded-[32px] border border-[#1A3C34]/10 bg-white/90 px-6 py-6 shadow-[0_30px_90px_rgba(26,60,52,0.12)]">
        <div className="flex flex-wrap items-end justify-between gap-4">
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
              Katalog
            </p>
            <h1 className="text-3xl font-serif text-[#1A3C34] md:text-4xl">
              Ürün yönetimi
            </h1>
            <p className="text-sm text-[#5C5C5C]">
              Ürün ekleyin, fiyat/stok güncelleyin ve pasife alın.
            </p>
          </div>
          <div className="flex items-center gap-2 rounded-full border border-[#1A3C34]/10 bg-white px-4 py-2 text-[11px] font-semibold uppercase tracking-[0.25em] text-[#1A3C34]/70">
            <AlertTriangle className="h-4 w-4" />
            Düşük stok: {lowStockCount}
          </div>
        </div>
      </section>

      <section className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)]">
        <section className="space-y-4 rounded-[28px] border border-[#E0D7C6] bg-white/90 px-6 py-6 shadow-[0_20px_60px_rgba(26,60,52,0.08)] lg:col-span-2">
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div>
              <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                SH-31
              </p>
              <h2 className="mt-2 text-2xl font-serif text-[#1A3C34]">
                CSV Import / Export
              </h2>
              <p className="mt-2 text-sm text-[#5C5C5C]">
                Export ile urunleri indirip duzenleyin, import ile toplu guncelleyin.
              </p>
            </div>
            <div className="flex flex-wrap gap-2">
              <Button
                type="button"
                variant="secondary"
                onClick={() => exportCsvMutation.mutate()}
                disabled={exportCsvMutation.isPending}
              >
                <Download className="mr-2 h-4 w-4" />
                {exportCsvMutation.isPending ? 'Indiriliyor...' : 'CSV Export'}
              </Button>
              <Button
                type="button"
                onClick={() => importCsvMutation.mutate()}
                disabled={importCsvMutation.isPending}
              >
                <Upload className="mr-2 h-4 w-4" />
                {importCsvMutation.isPending ? 'Import ediliyor...' : 'CSV Import'}
              </Button>
            </div>
          </div>

          <textarea
            value={csvInput}
            onChange={(e) => setCsvInput(e.target.value)}
            className="min-h-[180px] w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 py-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
            placeholder="id,categoryId,name,sku,type,priceCents,stock,isActive&#10;,12,Ornek Urun,SKU-ORNEK,PHYSICAL,9900,5,true"
          />

          {importReport ? (
            <div className="rounded-2xl border border-[#E5E5E0] bg-[#F8FAF8] px-4 py-3 text-sm text-[#1A3C34]">
              <p>
                Toplam satir: {importReport.totalRows} | Yeni: {importReport.created} | Guncel:{' '}
                {importReport.updated} | Bos satir: {importReport.skipped}
              </p>
              <p>Hata sayisi: {importReport.errors.length}</p>
              {importReport.errors.length > 0 ? (
                <div className="mt-2 max-h-36 overflow-auto rounded-lg border border-[#E5E5E0] bg-white px-3 py-2 text-xs">
                  {importReport.errors.map((error, index) => (
                    <p key={`${error.line}-${index}`}>
                      Satir {error.line}: {error.message}
                    </p>
                  ))}
                </div>
              ) : null}
            </div>
          ) : null}
        </section>

        <form
          onSubmit={handleCreate}
          className="space-y-4 rounded-[28px] border border-[#E0D7C6] bg-white/90 px-6 py-6 shadow-[0_20px_60px_rgba(26,60,52,0.08)]"
        >
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
              Yeni ürün
            </p>
            <h2 className="mt-2 text-2xl font-serif text-[#1A3C34]">
              Ürün oluştur
            </h2>
            <p className="mt-2 text-sm text-[#5C5C5C]">
              Fiyat alanı kuruş (örn: 12990 = ₺129,90).
            </p>
          </div>

          <div className="grid gap-3">
            <div className="space-y-1">
              <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                Ürün adı
              </label>
              <input
                value={createForm.name}
                onChange={(e) =>
                  setCreateForm((prev) => ({ ...prev, name: e.target.value }))
                }
                className="h-11 w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                placeholder="Örn: Premium Ürün"
                required
              />
            </div>

            <div className="space-y-1">
              <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                Alt başlık
              </label>
              <input
                value={createForm.subtitle}
                onChange={(e) =>
                  setCreateForm((prev) => ({ ...prev, subtitle: e.target.value }))
                }
                className="h-11 w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                placeholder="Örn: Özel müşteri taleplerine göre kişiselleştirilen ürün"
              />
            </div>

            <div className="grid gap-3 md:grid-cols-2">
              <div className="space-y-1">
                <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                  SKU
                </label>
                <input
                  value={createForm.sku}
                  onChange={(e) =>
                    setCreateForm((prev) => ({ ...prev, sku: e.target.value }))
                  }
                  className="h-11 w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                  placeholder="SKU-001"
                />
              </div>
              <div className="space-y-1">
                <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                  Tür
                </label>
                <select
                  value={createForm.type}
                  onChange={(e) =>
                    setCreateForm((prev) => ({
                      ...prev,
                      type: e.target.value as ProductType,
                    }))
                  }
                  className="h-11 w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                >
                  <option value="PHYSICAL">Fiziksel</option>
                  <option value="SERVICE">Hizmet</option>
                  <option value="WEIGHT">Kilo</option>
                  <option value="CUSTOM">Özel</option>
                </select>
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                Açıklama
              </label>
              <textarea
                value={createForm.description}
                onChange={(e) =>
                  setCreateForm((prev) => ({ ...prev, description: e.target.value }))
                }
                className="min-h-[110px] w-full resize-y rounded-2xl border border-[#E5E5E0] bg-white px-3 py-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                placeholder="Ürün açıklaması..."
              />
            </div>

            <div className="space-y-1">
              <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                Özellikler
              </label>
              <textarea
                value={createForm.features}
                onChange={(e) =>
                  setCreateForm((prev) => ({ ...prev, features: e.target.value }))
                }
                className="min-h-[110px] w-full resize-y rounded-2xl border border-[#E5E5E0] bg-white px-3 py-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                placeholder={'Her satıra 1 özellik yaz.\nÖrn: El yapımı\nÖrn: 2 yıl garanti'}
              />
              <p className="text-[11px] text-[#8A8A8A] md:text-xs">
                Her satır bir özellik olarak kaydedilir.
              </p>
            </div>

            <div className="space-y-1">
              <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                Kategori
              </label>
              <select
                value={createForm.categoryId}
                onChange={(e) =>
                  setCreateForm((prev) => ({
                    ...prev,
                    categoryId: e.target.value,
                  }))
                }
                className="h-11 w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                disabled={categoriesLoading || categoriesError}
                required
              >
                <option value="">Kategori seç*</option>
                {flatCategories.map((category) => (
                  <option
                    key={category.id}
                    value={String(category.id)}
                    style={{ paddingLeft: `${category.level * 20}px` }}
                  >
                    {'  '.repeat(category.level)}
                    {category.name}
                  </option>
                ))}
              </select>
              {categoriesLoading && (
                <p className="text-[11px] text-[#8A8A8A] md:text-xs">
                  Kategoriler yükleniyor...
                </p>
              )}
              {!categoriesLoading && categoriesError && (
                <p className="text-[11px] text-red-600 md:text-xs">
                  Kategoriler yüklenemedi.
                </p>
              )}
              {!categoriesLoading &&
                !categoriesError &&
                flatCategories &&
                flatCategories.length === 0 && (
                  <p className="text-[11px] text-[#8A8A8A] md:text-xs">
                    Henüz kategori yok. Önce kategori oluştur.
                  </p>
                )}
            </div>

            <div className="grid gap-3 md:grid-cols-2">
              <div className="space-y-1">
                <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                  Fiyat (kuruş)
                </label>
                <input
                  value={createForm.priceCents}
                  onChange={(e) =>
                    setCreateForm((prev) => ({
                      ...prev,
                      priceCents: e.target.value,
                    }))
                  }
                  className="h-11 w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                  placeholder="12990"
                  inputMode="numeric"
                  required
                />
              </div>
              <div className="space-y-1">
                <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                  Stok
                </label>
                <input
                  value={createForm.stock}
                  onChange={(e) =>
                    setCreateForm((prev) => ({ ...prev, stock: e.target.value }))
                  }
                  className="h-11 w-full rounded-2xl border border-[#E5E5E0] bg-white px-3 text-sm text-[#1A3C34] shadow-sm outline-none focus-visible:border-[#1A3C34] focus-visible:ring-2 focus-visible:ring-[#C5A059]/20"
                  placeholder="10"
                  inputMode="numeric"
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                Ürün görseli
              </label>
              <div className="flex flex-col gap-2 rounded-2xl border border-[#E5E5E0] bg-white px-3 py-3">
                <input
                  type="file"
                  accept="image/png,image/jpeg,image/webp"
                  onChange={async (e) => {
                    const file = e.target.files?.[0];
                    if (!file) return;
                    const result = await uploadMutation.mutateAsync(file);
                    setCreateForm((prev) => ({ ...prev, imageUrl: result.url }));
                    toast.success('Görsel yüklendi.');
                  }}
                  disabled={uploadMutation.isPending}
                  className="text-xs"
                />
                <input
                  value={createForm.imageUrl}
                  onChange={(e) =>
                    setCreateForm((prev) => ({ ...prev, imageUrl: e.target.value }))
                  }
                  className="h-10 w-full rounded-xl border border-[#E5E5E0] bg-white px-3 text-xs text-[#1A3C34] outline-none"
                  placeholder="https://api.../uploads/..."
                />
                {createForm.imageUrl.trim() && (
                  <p className="text-[11px] text-[#5C5C5C]">
                    Görsel kaydedilecek: {createForm.imageUrl.trim()}
                  </p>
                )}
              </div>
            </div>
          </div>

          <Button
            type="submit"
            disabled={createMutation.isPending}
            isLoading={createMutation.isPending}
            className="w-full"
          >
            Ürünü kaydet
          </Button>
        </form>

        <section className="rounded-[28px] border border-[#E0D7C6] bg-white/90 px-6 py-6 shadow-[0_20px_60px_rgba(26,60,52,0.08)]">
          <div className="flex flex-wrap items-end justify-between gap-4">
            <div>
              <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#AC9C7A]">
                Liste
              </p>
              <h2 className="mt-2 text-2xl font-serif text-[#1A3C34]">
                Ürünler
              </h2>
              <p className="mt-2 text-sm text-[#5C5C5C]">
                Toplam: {meta?.total ?? products?.length ?? 0}
              </p>
            </div>
          </div>

          {isLoading && (
            <div className="pt-6">
              <Spinner fullscreen />
            </div>
          )}

          {isError && !isLoading && (
            <div className="mt-6 rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
              Ürünler yüklenemedi. Token veya yetki problemi olabilir.
            </div>
          )}

          {!isLoading && !isError && (!products || products.length === 0) && (
            <div className="mt-6 rounded-2xl border border-[#E0D7C6] bg-white px-4 py-4 text-sm text-[#5C5C5C]">
              Ürün bulunamadı.
            </div>
          )}

          {!isLoading && !isError && products && products.length > 0 && (
            <div className="mt-6 overflow-hidden rounded-2xl border border-[#1A3C34]/10 bg-white">
              <div className="grid grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)_minmax(0,0.7fr)_minmax(0,0.8fr)_minmax(0,0.6fr)_minmax(0,0.9fr)] gap-3 border-b border-[#E5E5E0] px-4 py-3 text-[10px] font-semibold uppercase tracking-[0.25em] text-[#1A3C34]/60">
                <span>Ürün</span>
                <span>Kategori</span>
                <span>Tür</span>
                <span>Fiyat</span>
                <span>Stok</span>
                <span className="text-right">Aksiyon</span>
              </div>
              <div className="divide-y divide-[#F0F0EA]">
                {products.map((product) => {
                  const isEditing = editingId === product.id;
                  const stockLabel =
                    typeof product.stock === 'number' ? String(product.stock) : '-';
                  return (
                    <div
                      key={product.id}
                      className="grid grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)_minmax(0,0.7fr)_minmax(0,0.8fr)_minmax(0,0.6fr)_minmax(0,0.9fr)] gap-3 px-4 py-3 text-sm text-[#1A3C34]"
                    >
                      <div className="min-w-0">
                        {!isEditing ? (
                          <div className="min-w-0">
                            <p className="truncate font-semibold">{product.name}</p>
                            <p className="truncate text-xs text-[#5C5C5C]">
                              {product.sku ? `SKU: ${product.sku}` : `ID: ${product.id}`}
                            </p>
                          </div>
                        ) : (
                          <div className="grid gap-2">
                            <input
                              value={editForm.name}
                              onChange={(e) =>
                                setEditForm((prev) => ({
                                  ...prev,
                                  name: e.target.value,
                                }))
                              }
                              className="h-9 w-full rounded-xl border border-[#E5E5E0] bg-white px-3 text-sm outline-none"
                            />
                            <input
                              value={editForm.sku}
                              onChange={(e) =>
                                setEditForm((prev) => ({
                                  ...prev,
                                  sku: e.target.value,
                                }))
                              }
                              className="h-9 w-full rounded-xl border border-[#E5E5E0] bg-white px-3 text-xs outline-none"
                              placeholder="SKU"
                            />
                            <div className="grid gap-2">
                              <input
                                type="file"
                                accept="image/png,image/jpeg,image/webp"
                                onChange={async (e) => {
                                  const file = e.target.files?.[0];
                                  if (!file) return;
                                  const result = await uploadMutation.mutateAsync(file);
                                  setEditForm((prev) => ({ ...prev, imageUrl: result.url }));
                                  toast.success('Görsel yüklendi.');
                                }}
                                disabled={uploadMutation.isPending}
                                className="text-[11px]"
                              />
                              <input
                                value={editForm.imageUrl}
                                onChange={(e) =>
                                  setEditForm((prev) => ({
                                    ...prev,
                                    imageUrl: e.target.value,
                                  }))
                                }
                                className="h-9 w-full rounded-xl border border-[#E5E5E0] bg-white px-3 text-xs outline-none"
                                placeholder="imageUrl"
                              />
                            </div>
                          </div>
                        )}
                      </div>

                      <div>
                        {!isEditing ? (
                          <span className="text-sm text-[#5C5C5C]">
                            {typeof product.categoryId === 'number'
                              ? (categoryNameById.get(product.categoryId) ?? '-')
                              : '-'}
                          </span>
                        ) : (
                          <select
                            value={editForm.categoryId}
                            onChange={(e) =>
                              setEditForm((prev) => ({
                                ...prev,
                                categoryId: e.target.value,
                              }))
                            }
                            className="h-9 w-full rounded-xl border border-[#E5E5E0] bg-white px-2 text-xs outline-none"
                            disabled={categoriesLoading || categoriesError}
                            required
                          >
                            <option value="">Kategori seç*</option>
                            {flatCategories.map((category) => (
                              <option
                                key={category.id}
                                value={String(category.id)}
                                style={{ paddingLeft: `${category.level * 15}px` }}
                              >
                                {'  '.repeat(category.level)}
                                {category.name}
                              </option>
                            ))}
                          </select>
                        )}
                      </div>

                      <div>
                        {!isEditing ? (
                          <span className="text-sm text-[#5C5C5C]">
                            {formatType(product.type)}
                          </span>
                        ) : (
                          <select
                            value={editForm.type}
                            onChange={(e) =>
                              setEditForm((prev) => ({
                                ...prev,
                                type: e.target.value as ProductType,
                              }))
                            }
                            className="h-9 w-full rounded-xl border border-[#E5E5E0] bg-white px-2 text-xs outline-none"
                          >
                            <option value="PHYSICAL">Fiziksel</option>
                            <option value="SERVICE">Hizmet</option>
                            <option value="WEIGHT">Kilo</option>
                            <option value="CUSTOM">Özel</option>
                          </select>
                        )}
                      </div>

                      <div>
                        {!isEditing ? (
                          <span className="font-semibold">
                            {formatPrice(product.priceCents / 100)}
                          </span>
                        ) : (
                          <input
                            value={editForm.priceCents}
                            onChange={(e) =>
                              setEditForm((prev) => ({
                                ...prev,
                                priceCents: e.target.value,
                              }))
                            }
                            className="h-9 w-full rounded-xl border border-[#E5E5E0] bg-white px-3 text-xs outline-none"
                            inputMode="numeric"
                            placeholder="Kuruş"
                          />
                        )}
                      </div>

                      <div>
                        {!isEditing ? (
                          <span
                            className={`inline-flex rounded-full px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.18em] ${
                              typeof product.stock === 'number' && product.stock <= 5
                                ? 'bg-[#C5A059] text-[#3E2723]'
                                : 'bg-[#F3EEE3] text-[#3E2723]'
                            }`}
                          >
                            {stockLabel}
                          </span>
                        ) : (
                          <input
                            value={editForm.stock}
                            onChange={(e) =>
                              setEditForm((prev) => ({
                                ...prev,
                                stock: e.target.value,
                              }))
                            }
                            className="h-9 w-full rounded-xl border border-[#E5E5E0] bg-white px-3 text-xs outline-none"
                            inputMode="numeric"
                            placeholder="Stok"
                          />
                        )}
                      </div>

                      <div className="flex items-center justify-end gap-2">
                        {!isEditing ? (
                          <>
                            <button
                              type="button"
                              onClick={() => beginEdit(product)}
                              className="inline-flex items-center gap-2 rounded-full border border-[#1A3C34]/15 bg-white px-3 py-2 text-[10px] font-semibold uppercase tracking-[0.25em] text-[#1A3C34]"
                            >
                              <Pencil className="h-4 w-4" />
                              Düzenle
                            </button>
                            <button
                              type="button"
                              onClick={() => archiveMutation.mutate(product.id)}
                              disabled={archiveMutation.isPending}
                              className="inline-flex items-center gap-2 rounded-full border border-[#B04B4B]/30 bg-white px-3 py-2 text-[10px] font-semibold uppercase tracking-[0.25em] text-[#B04B4B] disabled:opacity-60"
                            >
                              <Archive className="h-4 w-4" />
                              Arşivle
                            </button>
                          </>
                        ) : (
                          <>
                            <button
                              type="button"
                              onClick={() => updateMutation.mutate(product.id)}
                              disabled={updateMutation.isPending}
                              className="inline-flex items-center gap-2 rounded-full bg-[#1A3C34] px-3 py-2 text-[10px] font-semibold uppercase tracking-[0.25em] text-white disabled:opacity-60"
                            >
                              <Save className="h-4 w-4" />
                              Kaydet
                            </button>
                            <button
                              type="button"
                              onClick={cancelEdit}
                              className="inline-flex items-center gap-2 rounded-full border border-[#1A3C34]/15 bg-white px-3 py-2 text-[10px] font-semibold uppercase tracking-[0.25em] text-[#1A3C34]"
                            >
                              <X className="h-4 w-4" />
                              İptal
                            </button>
                          </>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {!isLoading && !isError && meta && meta.totalPages > 1 && (
            <div className="mt-6 flex flex-wrap items-center justify-between gap-3 border-t border-[#E5E5E0] pt-4 text-xs text-[#5C5C5C]">
              <span className="text-[11px] font-semibold uppercase tracking-[0.25em] text-[#1A3C34]/60">
                Sayfa {meta.page} / {meta.totalPages}
              </span>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  disabled={meta.page <= 1}
                  className="inline-flex h-11 items-center gap-2 rounded-[var(--radius-md)] border border-[#E5E5E0] bg-white px-4 text-xs font-semibold uppercase tracking-[0.2em] text-[#1A3C34] shadow-sm disabled:cursor-not-allowed disabled:opacity-50"
                >
                  Önceki
                </button>
                <button
                  type="button"
                  onClick={() => setPage((p) => Math.min(meta.totalPages, p + 1))}
                  disabled={meta.page >= meta.totalPages}
                  className="inline-flex h-11 items-center gap-2 rounded-[var(--radius-md)] border border-[#1A3C34]/10 bg-[#1A3C34] px-4 text-xs font-semibold uppercase tracking-[0.2em] text-white shadow-sm disabled:cursor-not-allowed disabled:opacity-50"
                >
                  Sonraki
                </button>
              </div>
            </div>
          )}
        </section>
      </section>
    </div>
  );
}

'use client';

import Link from 'next/link';
import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import {
  ArrowUpRight,
  BarChart3,
  ClipboardList,
  CreditCard,
  Package,
  RefreshCcw,
  TrendingUp,
  Wallet,
  AlertTriangle,
  ShoppingBag,
} from 'lucide-react';

import Spinner from '@/components/common/Spinner';
import api from '@/services/api';
import { formatPrice } from '@/lib/format';

interface DashboardSummary {
  activeProducts: number; lowStockProducts: number;
  ordersTotal: number; ordersToday: number; revenueTodayCents: number;
}
interface DashboardReportsSummary {
  range: { from: string; to: string; days: number };
  ordersCount: number; revenueCents: number; averageOrderValueCents: number;
  topProducts: Array<{ productId: number; name: string; quantity: number; revenueCents: number }>;
}
interface OrderListResponse {
  data: Array<{ id: number; source: string; statusKey: string }>;
  meta: { total: number };
}
interface ReturnRequestSummary { id: number; }
interface PaginatedPayouts { data: Array<{ id: number }>; meta: { total: number }; }

const statusLabels: Record<string, string> = {
  CREATED: 'Oluşturuldu', NEW: 'Yeni', PAID: 'Ödendi',
  IN_PROGRESS: 'Hazırlanıyor', PREPARING: 'Hazırlanıyor',
  SHIPPED: 'Kargoda', DELIVERED: 'Teslim', COMPLETED: 'Tamamlandı',
  CANCELLED: 'İptal', RETURN_REQUESTED: 'İade Talebi',
  RETURNED: 'İade', RETURN_REJECTED: 'İade Ret',
  POS: 'POS', WEB: 'Web', MOBILE: 'Mobil', API: 'API',
};
const resolveLabel = (v: string) => statusLabels[v.toUpperCase()] ?? v;

const barColors = ['bg-[var(--primary-800)]', 'bg-amber-500', 'bg-violet-500', 'bg-blue-500', 'bg-red-400'];

export default function AdminReportsPage() {
  const summaryQ = useQuery<DashboardSummary>({
    queryKey: ['admin-reports-summary-kpi'],
    queryFn: async () => (await api.get<DashboardSummary>('/dashboard/summary')).data,
  });
  const reportsQ = useQuery<DashboardReportsSummary>({
    queryKey: ['admin-reports-period-summary'],
    queryFn: async () => (await api.get<DashboardReportsSummary>('/dashboard/reports/summary')).data,
  });
  const ordersQ = useQuery<OrderListResponse>({
    queryKey: ['admin-reports-orders-sample'],
    queryFn: async () => (await api.get<OrderListResponse>('/platform/orders?page=1&pageSize=80')).data,
  });
  const returnsQ = useQuery<ReturnRequestSummary[]>({
    queryKey: ['admin-reports-pending-returns'],
    queryFn: async () => (await api.get<ReturnRequestSummary[]>('/platform/return-requests?status=PENDING')).data,
  });
  const payoutsQ = useQuery<PaginatedPayouts>({
    queryKey: ['admin-reports-pending-payouts'],
    queryFn: async () => (await api.get<PaginatedPayouts>('/platform/finance/payouts?status=pending&page=1&pageSize=20')).data,
  });

  const isLoading = summaryQ.isLoading || reportsQ.isLoading;
  const isError = summaryQ.isError || reportsQ.isError;
  const reports = reportsQ.data;
  const summary = summaryQ.data;
  const ordersSample = ordersQ.data?.data ?? [];
  const pendingReturns = returnsQ.data?.length ?? 0;
  const pendingPayouts = payoutsQ.data?.meta?.total ?? 0;

  const rangeLabel = reports
    ? `${new Date(reports.range.from).toLocaleDateString('tr-TR')} – ${new Date(reports.range.to).toLocaleDateString('tr-TR')}`
    : '—';

  const sourceDistribution = useMemo(() => {
    const counts = ordersSample.reduce<Record<string, number>>((acc, o) => {
      const k = (o.source ?? 'UNKNOWN').toUpperCase(); acc[k] = (acc[k] ?? 0) + 1; return acc;
    }, {});
    return Object.entries(counts).map(([k, c]) => ({ key: k, count: c })).sort((a, b) => b.count - a.count);
  }, [ordersSample]);

  const statusDistribution = useMemo(() => {
    const counts = ordersSample.reduce<Record<string, number>>((acc, o) => {
      const k = (o.statusKey ?? 'UNKNOWN').toUpperCase(); acc[k] = (acc[k] ?? 0) + 1; return acc;
    }, {});
    return Object.entries(counts).map(([k, c]) => ({ key: k, count: c })).sort((a, b) => b.count - a.count);
  }, [ordersSample]);

  return (
    <div className="space-y-8">

      {/* ── Header ── */}
      <div className="flex items-start justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-[22px] font-semibold text-[var(--primary-800)]">Operasyon Raporları</h1>
          <p className="mt-1 text-sm text-[var(--neutral-600)]">Satış, ürün ve operasyon metriklerini izleyin.</p>
        </div>
        <span className="text-xs font-medium text-[var(--neutral-500)]">📅 {rangeLabel}</span>
      </div>

      {isLoading && <Spinner label="Rapor verileri yükleniyor..." />}
      {isError && (
        <div className="flex items-center gap-2 rounded-[var(--radius-md)] border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          <AlertTriangle className="h-4 w-4" /> Rapor verileri alınamadı.
        </div>
      )}

      {!isLoading && !isError && reports && summary && (
        <>
          {/* ── KPIs ── */}
          <div className="grid grid-cols-2 gap-x-8 gap-y-6 sm:grid-cols-3 lg:grid-cols-6">
            {[
              { label: '30 Gün Ciro', value: formatPrice(reports.revenueCents), icon: TrendingUp },
              { label: '30 Gün Sipariş', value: String(reports.ordersCount), icon: ShoppingBag },
              { label: 'Ort. Sepet', value: formatPrice(reports.averageOrderValueCents), icon: BarChart3 },
              { label: 'Bugün Sipariş', value: String(summary.ordersToday), icon: ClipboardList },
              { label: 'Bugün Ciro', value: formatPrice(summary.revenueTodayCents), icon: CreditCard },
              { label: 'Düşük Stok', value: String(summary.lowStockProducts), icon: Package },
            ].map(({ label, value, icon: Icon }) => (
              <div key={label}>
                <p className="text-[11px] font-semibold uppercase tracking-[0.25em] text-[var(--neutral-500)]">{label}</p>
                <div className="mt-1 flex items-end gap-2">
                  <span className="text-xl font-semibold text-[var(--primary-800)]">{value}</span>
                  <Icon className="mb-0.5 h-4 w-4 text-[var(--neutral-400)]" />
                </div>
              </div>
            ))}
          </div>

          {/* ── Divider ── */}
          <div className="border-t border-[var(--neutral-200)]" />

          {/* ── Top Products + Distributions ── */}
          <div className="grid gap-10 xl:grid-cols-[1fr_320px]">

            {/* Top Products Table */}
            <div>
              <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[var(--neutral-500)] mb-4">
                En Çok Satan Ürünler — Son 30 Gün
              </p>
              {reports.topProducts.length === 0 ? (
                <p className="text-sm text-[var(--neutral-500)]">Bu dönemde ürün satışı yok.</p>
              ) : (
                <table className="min-w-full text-sm">
                  <thead>
                    <tr className="border-b border-[var(--neutral-200)]">
                      {['Sıra', 'Ürün', 'Adet', 'Ciro'].map((h) => (
                        <th key={h} className={`pb-3 pr-6 text-left text-[11px] font-semibold uppercase tracking-[0.25em] text-[var(--neutral-500)] ${h === 'Ciro' ? 'text-right' : ''}`}>{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--neutral-100)]">
                    {reports.topProducts.slice(0, 10).map((p, i) => (
                      <tr key={p.productId} className="hover:bg-[var(--neutral-50)] transition-colors">
                        <td className="py-3 pr-6 text-[13px] font-bold text-[var(--neutral-400)]">{i + 1}</td>
                        <td className="py-3 pr-6 font-medium text-[var(--primary-800)]">{p.name}</td>
                        <td className="py-3 pr-6 text-[var(--neutral-600)]">{p.quantity}</td>
                        <td className="py-3 text-right font-semibold text-[var(--primary-800)]">{formatPrice(p.revenueCents)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>

            {/* Right Column */}
            <div className="space-y-8">
              {/* Source Distribution */}
              <div>
                <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[var(--neutral-500)] mb-4">
                  Kaynak Dağılımı
                  <span className="ml-2 normal-case tracking-normal font-normal text-[var(--neutral-400)]">({ordersSample.length} örnek)</span>
                </p>
                {sourceDistribution.length === 0
                  ? <p className="text-sm text-[var(--neutral-500)]">Veri yok.</p>
                  : (
                    <div className="space-y-3">
                      {sourceDistribution.map((entry, i) => {
                        const pct = ordersSample.length > 0 ? Math.round((entry.count / ordersSample.length) * 100) : 0;
                        return (
                          <div key={entry.key}>
                            <div className="flex items-center justify-between text-xs mb-1">
                              <span className="font-medium text-[var(--neutral-700)]">{resolveLabel(entry.key)}</span>
                              <span className="text-[var(--neutral-500)]">{entry.count} ({pct}%)</span>
                            </div>
                            <div className="h-1 rounded-full bg-[var(--neutral-100)]">
                              <div className={`h-full rounded-full ${barColors[i % barColors.length]}`} style={{ width: `${pct}%` }} />
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )
                }
              </div>

              {/* Status Distribution */}
              <div>
                <p className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[var(--neutral-500)] mb-4">Durum Dağılımı</p>
                {statusDistribution.length === 0
                  ? <p className="text-sm text-[var(--neutral-500)]">Veri yok.</p>
                  : (
                    <div className="divide-y divide-[var(--neutral-100)]">
                      {statusDistribution.slice(0, 7).map((entry) => (
                        <div key={entry.key} className="flex items-center justify-between py-2 text-sm">
                          <span className="text-[var(--neutral-700)]">{resolveLabel(entry.key)}</span>
                          <span className="font-semibold text-[var(--primary-800)]">{entry.count}</span>
                        </div>
                      ))}
                    </div>
                  )
                }
              </div>
            </div>
          </div>

          {/* ── Divider ── */}
          <div className="border-t border-[var(--neutral-200)]" />

          {/* ── Operation Links ── */}
          <div className="grid gap-6 md:grid-cols-3">
            {[
              { icon: RefreshCcw, label: 'Bekleyen İade', value: pendingReturns, href: '/admin/orders', link: 'Siparişlere Git' },
              { icon: Wallet, label: 'Bekleyen Payout', value: pendingPayouts, href: '/admin/finance/payouts', link: 'Payout Ekranı' },
              { icon: CreditCard, label: 'Ödeme Debug', value: null, href: '/admin/payments/webhooks', link: 'Webhook Listesi' },
            ].map(({ icon: Icon, label, value, href, link }) => (
              <div key={label}>
                <div className="flex items-center gap-2 mb-1">
                  <Icon className="h-4 w-4 text-[var(--neutral-500)]" />
                  <p className="text-[11px] font-semibold uppercase tracking-[0.25em] text-[var(--neutral-500)]">{label}</p>
                </div>
                {value !== null && (
                  <p className="text-3xl font-semibold text-[var(--primary-800)] mb-2">{value}</p>
                )}
                <Link href={href} className="inline-flex items-center gap-1 text-xs font-semibold text-[var(--primary-800)] hover:underline underline-offset-2">
                  {link} <ArrowUpRight className="h-3.5 w-3.5" />
                </Link>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

'use client';

import Link from 'next/link';
import { useMemo, useState } from 'react';
import { usePathname } from 'next/navigation';
import { useQuery } from '@tanstack/react-query';
import {
  AlertTriangle,
  ArrowUpRight,
  DatabaseZap,
  Download,
  Mail,
  MessageSquareWarning,
  Shield,
} from 'lucide-react';

import Spinner from '@/components/common/Spinner';
import RiskScoreBadge from '@/components/common/RiskScoreBadge';
import { useCapabilities } from '@/hooks/useCapabilities';
import api from '@/services/api';

type OutboxMetrics = {
  totalCount: number;
  processedCount: number;
  pendingCount: number;
  retryCount: number;
  failedCount: number;
  deadLetterCount: number;
};

type OutboxEventRow = {
  id: number;
  eventType: string;
  aggregateType: string;
  aggregateId: string;
  attemptCount: number;
  lastError?: string | null;
  deadLetteredAt?: string | null;
  processedAt?: string | null;
  createdAt: string;
};

type PaginatedOutbox = {
  data: OutboxEventRow[];
  meta: { total: number; page: number; pageSize: number; totalPages: number };
};

type AuditLogRow = {
  id: number;
  actorRole: string;
  actorUserId: number;
  actionType: string;
  targetType: string;
  targetId: string;
  createdAt: string;
  actorUser?: { id: number; name?: string | null; phone?: string | null } | null;
};

type PaginatedAuditLogs = {
  data: AuditLogRow[];
  meta: { total: number; page: number; pageSize: number; totalPages: number };
};

type WebhookEventRow = {
  id: number;
  provider: string;
  status: string;
  receivedAt?: string | null;
  processedAt?: string | null;
};

const formatDateTime = (value?: string | null) =>
  value ? new Date(value).toLocaleString('tr-TR') : '-';

const normalizeStatus = (value?: string | null) =>
  String(value ?? '').trim().toUpperCase();

const normalizeAction = (value?: string | null) =>
  String(value ?? '').trim().toUpperCase();

export default function RiskControlPage() {
  const { canAny } = useCapabilities();
  const pathname = usePathname();
  const isPlatformPath = pathname.startsWith('/platform');
  const [tab, setTab] = useState<'overview' | 'audit' | 'outbox' | 'governance'>(
    'overview',
  );
  const basePath = isPlatformPath ? '/platform' : '/admin';
  const canViewRiskHub = canAny(['VIEW_AUDIT', 'VIEW_OUTBOX']);

  const metricsQuery = useQuery<OutboxMetrics>({
    queryKey: ['risk-control-outbox-metrics'],
    enabled: canViewRiskHub,
    queryFn: async () => {
      const res = await api.get<OutboxMetrics>('/platform/outbox/metrics');
      return res.data;
    },
  });

  const outboxEventsQuery = useQuery<PaginatedOutbox>({
    queryKey: ['risk-control-outbox-events'],
    enabled: canViewRiskHub,
    queryFn: async () => {
      const res = await api.get<PaginatedOutbox>(
        '/platform/outbox/events?page=1&pageSize=20',
      );
      return res.data;
    },
  });

  const auditQuery = useQuery<PaginatedAuditLogs>({
    queryKey: ['risk-control-audit'],
    enabled: canViewRiskHub,
    queryFn: async () => {
      const res = await api.get<PaginatedAuditLogs>(
        '/platform/audit/logs?page=1&pageSize=20',
      );
      return res.data;
    },
  });

  const webhookQuery = useQuery<WebhookEventRow[]>({
    queryKey: ['risk-control-webhooks'],
    enabled: canViewRiskHub,
    queryFn: async () => {
      const res = await api.get<WebhookEventRow[]>(
        '/payments/admin/webhook-events?provider=IYZICO',
      );
      return res.data;
    },
  });

  const isLoading =
    metricsQuery.isLoading ||
    outboxEventsQuery.isLoading ||
    auditQuery.isLoading ||
    webhookQuery.isLoading;

  const outboxMetrics = metricsQuery.data;
  const outboxEvents = outboxEventsQuery.data?.data ?? [];
  const auditLogs = auditQuery.data?.data ?? [];
  const webhookRows = webhookQuery.data ?? [];

  const riskScore = useMemo(() => {
    if (!outboxMetrics) return 0;
    const total = Math.max(outboxMetrics.totalCount, 1);
    const failedRatio =
      ((outboxMetrics.failedCount + outboxMetrics.deadLetterCount) / total) * 100;
    const retryRatio = (outboxMetrics.retryCount / total) * 100;
    const overrideCount = auditLogs.filter((row) => {
      const action = normalizeAction(row.actionType);
      return (
        action.includes('FORCE') ||
        action.includes('OVERRIDE') ||
        action.includes('ROLE_CHANGE')
      );
    }).length;
    const webhookFailed = webhookRows.filter(
      (row) => normalizeStatus(row.status) === 'FAILED',
    ).length;
    const webhookRatio =
      webhookRows.length > 0 ? (webhookFailed / webhookRows.length) * 100 : 0;
    const score = failedRatio * 0.45 + retryRatio * 0.2 + overrideCount * 2 + webhookRatio * 0.35;
    return Math.max(0, Math.min(100, Math.round(score)));
  }, [auditLogs, outboxMetrics, webhookRows]);

  const criticalAuditRows = useMemo(
    () =>
      auditLogs.filter((row) => {
        const action = normalizeAction(row.actionType);
        return (
          action.includes('FORCE') ||
          action.includes('OVERRIDE') ||
          action.includes('ROLE_CHANGE')
        );
      }),
    [auditLogs],
  );

  if (!canViewRiskHub) {
    return (
      <section className="rounded-[var(--radius-xl)] border border-red-200 bg-red-50 px-6 py-6">
        <p className="text-sm text-red-700">
          Risk & Control ekranini goruntulemek icin yetkiniz yok.
        </p>
      </section>
    );
  }

  return (
    <div className="space-y-6">
      <section className="rounded-[var(--radius-2xl)] border border-[var(--neutral-200)] bg-gradient-to-br from-[#FFF8EB] via-white to-[#EEF7FF] px-6 py-6">
        <div className="flex flex-wrap items-end justify-between gap-3">
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.28em] text-[var(--neutral-500)]">
              Risk & Control
            </p>
            <h1 className="mt-2 text-3xl font-serif text-[var(--primary-800)]">
              Operasyon Güvenliği Merkezi
            </h1>
            <p className="mt-2 text-sm text-[var(--neutral-600)]">
              Audit, outbox, concurrency ve export governance sinyallerini tek panelde izleyin.
            </p>
          </div>
          <RiskScoreBadge score={riskScore} label="Risk Score" />
        </div>
        <div className="mt-4 flex flex-wrap gap-2">
          {([
            { key: 'overview', label: 'Overview' },
            { key: 'audit', label: 'Audit Feed' },
            { key: 'outbox', label: 'Outbox' },
            { key: 'governance', label: 'Governance' },
          ] as const).map((item) => (
            <button
              key={item.key}
              type="button"
              onClick={() => setTab(item.key)}
              className={`rounded-full border px-4 py-2 text-xs font-semibold uppercase tracking-[0.18em] ${
                tab === item.key
                  ? 'border-[var(--primary-800)] bg-[var(--primary-800)] text-white'
                  : 'border-[var(--neutral-200)] bg-white text-[var(--primary-800)]'
              }`}
            >
              {item.label}
            </button>
          ))}
        </div>
      </section>

      {isLoading ? (
        <section className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-6 py-10">
          <Spinner label="Risk verileri yükleniyor..." />
        </section>
      ) : null}

      {!isLoading && tab === 'overview' ? (
        <section className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
          <div className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-5 py-5">
            <p className="text-xs font-semibold uppercase tracking-[0.2em] text-[var(--neutral-500)]">
              Outbox backlog
            </p>
            <p className="mt-2 text-3xl font-serif text-[var(--primary-800)]">
              {outboxMetrics?.pendingCount ?? 0}
            </p>
            <p className="mt-1 text-sm text-[var(--neutral-600)]">
              Retry: {outboxMetrics?.retryCount ?? 0} · Dead-letter: {outboxMetrics?.deadLetterCount ?? 0}
            </p>
          </div>

          <div className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-5 py-5">
            <p className="text-xs font-semibold uppercase tracking-[0.2em] text-[var(--neutral-500)]">
              Payment webhook health
            </p>
            <p className="mt-2 text-3xl font-serif text-[var(--primary-800)]">
              {webhookRows.filter((row) => normalizeStatus(row.status) === 'FAILED').length}
            </p>
            <p className="mt-1 text-sm text-[var(--neutral-600)]">Failed event</p>
          </div>

          <div className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-5 py-5">
            <p className="text-xs font-semibold uppercase tracking-[0.2em] text-[var(--neutral-500)]">
              Override yoğunluğu
            </p>
            <p className="mt-2 text-3xl font-serif text-[var(--primary-800)]">
              {criticalAuditRows.length}
            </p>
            <p className="mt-1 text-sm text-[var(--neutral-600)]">
              Son 20 audit kaydı içindeki kritik işlem
            </p>
          </div>

          <div className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-5 py-5">
            <p className="text-xs font-semibold uppercase tracking-[0.2em] text-[var(--neutral-500)]">
              SMTP/SMS health
            </p>
            <p className="mt-2 text-lg font-semibold text-amber-700">Endpoint gerekli</p>
            <p className="mt-1 text-sm text-[var(--neutral-600)]">Aggregate delivery health bekleniyor.</p>
          </div>

          <div className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-5 py-5">
            <p className="text-xs font-semibold uppercase tracking-[0.2em] text-[var(--neutral-500)]">
              POS offline ratio
            </p>
            <p className="mt-2 text-lg font-semibold text-amber-700">Telemetry gerekli</p>
            <p className="mt-1 text-sm text-[var(--neutral-600)]">Offline/online sipariş oranı için pipeline gerekli.</p>
          </div>

          <div className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-5 py-5">
            <p className="text-xs font-semibold uppercase tracking-[0.2em] text-[var(--neutral-500)]">
              Support mode
            </p>
            {isPlatformPath ? (
              <Link
                href={`${basePath}/support`}
                className="mt-3 inline-flex items-center gap-2 rounded-full border border-[var(--neutral-200)] bg-white px-4 py-2 text-xs font-semibold uppercase tracking-[0.18em] text-[var(--primary-800)]"
              >
                Destek moduna git <ArrowUpRight className="h-4 w-4" />
              </Link>
            ) : (
              <p className="mt-3 text-sm text-[var(--neutral-600)]">
                Support Mode yalnizca platform panelinde acik.
              </p>
            )}
          </div>
        </section>
      ) : null}

      {!isLoading && tab === 'audit' ? (
        <section className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-6 py-6">
          <h2 className="text-xl font-serif text-[var(--primary-800)]">Audit Feed</h2>
          <div className="mt-4 space-y-2">
            {auditLogs.length === 0 ? (
              <p className="text-sm text-[var(--neutral-600)]">Audit kaydı bulunamadı.</p>
            ) : (
              auditLogs.map((row) => (
                <div
                  key={row.id}
                  className="rounded-lg border border-[var(--neutral-200)] bg-[var(--neutral-50)] px-4 py-3 text-sm"
                >
                  <p className="font-semibold text-[var(--primary-800)]">
                    {row.actionType} · {row.targetType}#{row.targetId}
                  </p>
                  <p className="text-[var(--neutral-600)]">
                    {row.actorUser?.name || `User#${row.actorUserId}`} ({row.actorRole}) ·{' '}
                    {formatDateTime(row.createdAt)}
                  </p>
                </div>
              ))
            )}
          </div>
        </section>
      ) : null}

      {!isLoading && tab === 'outbox' ? (
        <section className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-6 py-6">
          <h2 className="text-xl font-serif text-[var(--primary-800)]">Outbox Monitor</h2>
          <div className="mt-4 overflow-x-auto">
            <table className="min-w-full text-left text-sm">
              <thead>
                <tr className="border-b border-[var(--neutral-200)] text-[10px] uppercase tracking-[0.2em] text-[var(--neutral-500)]">
                  <th className="py-3 pr-3">Event</th>
                  <th className="py-3 pr-3">Aggregate</th>
                  <th className="py-3 pr-3">Attempt</th>
                  <th className="py-3 pr-3">Status</th>
                  <th className="py-3 pr-3">Created</th>
                </tr>
              </thead>
              <tbody>
                {outboxEvents.map((row) => {
                  const status = row.deadLetteredAt
                    ? 'DEAD_LETTER'
                    : row.processedAt
                      ? 'PROCESSED'
                      : row.attemptCount > 0
                        ? 'RETRY'
                        : 'PENDING';
                  return (
                    <tr key={row.id} className="border-b border-[var(--neutral-100)]">
                      <td className="py-3 pr-3 font-semibold text-[var(--primary-800)]">
                        {row.eventType}
                      </td>
                      <td className="py-3 pr-3 text-[var(--neutral-600)]">
                        {row.aggregateType}#{row.aggregateId}
                      </td>
                      <td className="py-3 pr-3 text-[var(--neutral-700)]">{row.attemptCount}</td>
                      <td className="py-3 pr-3 text-[var(--neutral-700)]">{status}</td>
                      <td className="py-3 pr-3 text-[var(--neutral-600)]">
                        {formatDateTime(row.createdAt)}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </section>
      ) : null}

      {!isLoading && tab === 'governance' ? (
        <section className="grid gap-4 lg:grid-cols-2">
          <div className="rounded-[var(--radius-xl)] border border-[var(--neutral-200)] bg-white px-6 py-6">
            <h2 className="text-xl font-serif text-[var(--primary-800)]">Export Governance</h2>
            <ul className="mt-4 space-y-2 text-sm text-[var(--neutral-700)]">
              <li className="flex items-start gap-2">
                <Download className="mt-0.5 h-4 w-4 text-[var(--primary-800)]" />
