import { ArrowUpRight, Users } from 'lucide-react';
import { useMemo, useState } from 'react';
import { useQuery } from '@tanstack/react-query';

import Spinner from '@/components/common/Spinner';
import api from '@/services/api';
import { formatDate } from '@/utils/helpers';

type PaginationMeta = {
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
};

type SellerRow = {
  id: number;
  userId: number;
  slug: string;
  displayName: string;
  description?: string | null;
  logoUrl?: string | null;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
};

type PaginatedSellers = {
  data: SellerRow[];
  meta: PaginationMeta;
};

const resolveApiErrorMessage = (error: unknown, fallback: string) => {
  if (!error || typeof error !== 'object') return fallback;
  if (!('response' in error)) return fallback;
  const response = (error as { response?: unknown }).response;
  if (!response || typeof response !== 'object') return fallback;
  if (!('data' in response)) return fallback;
  const data = (response as { data?: unknown }).data;
  if (!data || typeof data !== 'object') return fallback;
  if (!('message' in data)) return fallback;
  const message = (data as { message?: unknown }).message;
  if (Array.isArray(message)) return message.map(String).join(', ');
  if (typeof message === 'string') return message;
  return fallback;
};

export default function AdminSellersPage() {
  const [isActive, setIsActive] = useState<'true' | 'false' | ''>('');
  const [page, setPage] = useState(1);
  const [pageSize] = useState(20);

  const {
    data: payload,
    isLoading,
    isError,
    error,
  } = useQuery<PaginatedSellers>({
    queryKey: ['platform-sellers', { isActive, page, pageSize }],
    queryFn: async () => {
      const res = await api.get<PaginatedSellers>('/platform/sellers', {
        params: {
          isActive: isActive || undefined,
          page,
          pageSize,
        },
      });
      return res.data;
    },
  });

  const items = payload?.data ?? [];
  const meta = payload?.meta;

  const summary = useMemo(() => {
    const activeCount = items.filter((s) => s.isActive).length;
    const inactiveCount = items.length - activeCount;
    return { activeCount, inactiveCount };
  }, [items]);

  return (
    <div className="space-y-6">
      <section className="border-b border-[var(--neutral-200)] pb-6">
