    apiUrl: typeof row.apiUrl === 'string' ? row.apiUrl : '',
    apiKey: typeof row.apiKey === 'string' ? row.apiKey : '',
    sender: typeof row.sender === 'string' ? row.sender : 'NUTOPIANO',
    orderCreatedEnabled: Boolean(
