  const resolveMismatchDecision = useCallback((decision: PosMismatchDecision) => {
    const resolver = mismatchDecisionResolverRef.current;
    mismatchDecisionResolverRef.current = null;
    setMismatchModal(null);
    if (resolver) {
      resolver(decision);
    }
  }, []);

  useEffect(() => {
    return () => {
