                    <p className="text-xs font-semibold uppercase tracking-[0.1em] text-[#1A3C34]/70">
                      Sepet
                    </p>
                    <p className="text-xs text-[#1A3C34]/70">{cartItems.length} kalem</p>
                  </div>
                  {cartItems.length === 0 ? (
                    <p className="mt-2 text-sm text-[#5C5C5C]">
