      </header>

      {/* Body */}
      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar — Desktop */}
        <aside className={`hidden lg:flex flex-col w-[260px] flex-shrink-0 ${sidebarBg} sticky top-14 h-[calc(100vh-3.5rem)]`}>
