        {/* Main Content */}
        <main className="flex-1 overflow-y-auto">
          <div className="max-w-[1440px] mx-auto px-4 py-6 md:px-6 md:py-8 space-y-6">
            {children}
          </div>
        </main>
      </div>

      {/* Mobile Drawer */}
      {mobileNavOpen && (
        <div className="fixed inset-0 z-50 lg:hidden">
          <button
            type="button"
            aria-label="Menüyü kapat"
            onClick={() => setMobileNavOpen(false)}
            className="absolute inset-0 bg-black/40 backdrop-blur-sm"
          />
          <div className={`absolute left-0 top-0 h-full w-[280px] ${sidebarBg} flex flex-col shadow-2xl`}>
            <div className="flex items-center justify-between px-4 py-3 border-b border-white/10">
              <div className="flex items-center gap-2">
                <div
                  className="h-6 w-6 rounded-md flex items-center justify-center text-white text-[11px] font-bold"
                  style={{ backgroundColor: topBarAccent }}
                >
                  N
                </div>
                <p className="text-[12px] font-semibold text-white">
                  {isStaff ? 'Personel Paneli' : 'Satıcı Paneli'}
                </p>
              </div>
              <button
                type="button"
                onClick={() => setMobileNavOpen(false)}
                className="inline-flex h-8 w-8 items-center justify-center rounded-lg text-white/60 hover:bg-white/10 hover:text-white transition"
                aria-label="Kapat"
              >
                <X className="w-[18px] h-[18px]" />
              </button>
            </div>
            <SidebarContent {...sidebarProps} />
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Authentication hook
 */

import { useCallback, useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import type { RootState } from '@/store';

export interface User {
  id: number;
  email: string;
  name: string;
  role: string;
}

export interface AuthState {
  user: User | null;
  token: string | null;
  isLoading: boolean;
  error: string | null;
}

export function useAuth() {
  const dispatch = useDispatch();
  const { user, token, status, error } = useSelector((state: RootState) => state.user);
  const isLoading = status === 'authenticating';

  const login = useCallback(
    async (email: string, password: string) => {
      // Will be implemented with Redux dispatch
      console.log('Login:', email);
    },
    [dispatch],
  );

  const logout = useCallback(() => {
    // Will be implemented with Redux dispatch
    console.log('Logout');
  }, [dispatch]);

  const register = useCallback(
    async (email: string, password: string, name: string) => {
      // Will be implemented with Redux dispatch
      console.log('Register:', email);
    },
    [dispatch],
  );

  const isAuthenticated = !!token && !!user;

  return {
    user,
    token,
    isLoading,
    error,
    isAuthenticated,
    login,
    logout,
    register,
  };
}

/**
 * Data fetching hook with loading and error states
 */

import { useEffect, useState, useCallback, useRef } from 'react';
import type { ApiResponse } from '@/types';

export interface UseFetchOptions {
  method?: 'GET' | 'POST' | 'PATCH' | 'DELETE' | 'PUT';
  headers?: Record<string, string>;
  body?: any;
  skip?: boolean;
  dependencies?: any[];
}

export interface UseFetchState<T> {
  data: T | null;
  loading: boolean;
  error: Error | null;
  statusCode?: number;
}

export function useFetch<T = any>(
  url: string,
  options: UseFetchOptions = {},
): UseFetchState<T> & { refetch: () => Promise<void> } {
  const { method = 'GET', headers = {}, body, skip = false, dependencies = [url] } = options;

  const [state, setState] = useState<UseFetchState<T>>({
    data: null,
    loading: true,
    error: null,
  });

  const abortControllerRef = useRef<AbortController | null>(null);

  const fetchData = useCallback(async () => {
    if (skip) {
      setState((prev) => ({ ...prev, loading: false }));
      return;
    }

    // Cancel previous request
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    abortControllerRef.current = new AbortController();

    try {
      setState((prev) => ({ ...prev, loading: true, error: null }));

      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          ...headers,
        },
        body: body ? JSON.stringify(body) : undefined,
        signal: abortControllerRef.current.signal,
      });

      if (!response.ok) {
        throw new Error(`HTTP Error: ${response.status}`);
      }

      const json: ApiResponse<T> = await response.json();

      setState({
        data: json.data || null,
        loading: false,
        error: null,
        statusCode: response.status,
      });
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') {
        // Request was cancelled, don't update state
        return;
      }

      setState({
        data: null,
        loading: false,
        error: error instanceof Error ? error : new Error('Unknown error'),
      });
    }
  }, [url, method, headers, body, skip]);

  useEffect(() => {
    fetchData();

    return () => {
      // Cancel request on unmount
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, dependencies);

  return {
    ...state,
    refetch: fetchData,
  };
}

/**
 * Form state management hook
 */

import { useState, useCallback } from 'react';
import type { FormState, FormError } from '@/types';

export interface UseFormOptions<T> {
  initialValues: T;
  onSubmit: (values: T) => Promise<void>;
  validate?: (values: T) => FormError[];
}

export function useForm<T extends Record<string, any>>(options: UseFormOptions<T>) {
  const { initialValues, onSubmit, validate } = options;

  const [values, setValues] = useState<T>(initialValues);
  const [errors, setErrors] = useState<FormError[]>([]);
  const [touched, setTouched] = useState<Record<string, boolean>>({});
  const [isDirty, setIsDirty] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const getFieldError = useCallback(
    (fieldName: string): string | undefined => {
      return errors.find((error) => error.field === fieldName)?.message;
    },
    [errors],
  );

  const setFieldValue = useCallback((field: string, value: any) => {
    setValues((prev) => ({
      ...prev,
      [field]: value,
    }));
    setIsDirty(true);

    // Clear error for this field
    setErrors((prev) => prev.filter((error) => error.field !== field));
  }, []);

  const setFieldError = useCallback((field: string, message: string) => {
    setErrors((prev) => {
      // Remove existing error for this field
      const filtered = prev.filter((error) => error.field !== field);
      return [...filtered, { field, message }];
    });
  }, []);

  const setFieldTouched = useCallback((field: string, touched: boolean) => {
    setTouched((prev) => ({
      ...prev,
      [field]: touched,
    }));
  }, []);

  const resetForm = useCallback(() => {
    setValues(initialValues);
    setErrors([]);
    setTouched({});
    setIsDirty(false);
    setIsSubmitting(false);
  }, [initialValues]);

  const handleSubmit = useCallback(
    async (e: React.FormEvent<HTMLFormElement>) => {
      e.preventDefault();

      // Run validation if provided
      if (validate) {
        const validationErrors = validate(values);
        if (validationErrors.length > 0) {
          setErrors(validationErrors);
          return;
        }
      }

      setIsSubmitting(true);

      try {
        await onSubmit(values);
        // Reset form after successful submission
        resetForm();
      } catch (error) {
        // Error is handled by caller
        console.error('Form submission error:', error);
      } finally {
        setIsSubmitting(false);
      }
    },
    [values, validate, onSubmit, resetForm],
  );

  const isValid = errors.length === 0;

  return {
    values,
    errors,
    touched,
    isDirty,
    isValid,
    isSubmitting,
    setFieldValue,
    setFieldError,
    setFieldTouched,
    getFieldError,
    resetForm,
    handleSubmit,
  };
}

/**
 * Local storage hook with type safety
 */

import { useState, useEffect, useCallback } from 'react';

export function useLocalStorage<T>(key: string, initialValue: T) {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      // Check if value exists in localStorage
      if (typeof window === 'undefined') {
        return initialValue;
      }

      const item = window.localStorage.getItem(key);

      if (!item) {
        return initialValue;
      }

      return JSON.parse(item) as T;
    } catch (error) {
      console.error(`Error reading from localStorage key "${key}":`, error);
      return initialValue;
    }
  });

  // Update localStorage and state
  const setValue = useCallback(
    (value: T | ((val: T) => T)) => {
      try {
        // Allow value to be a function for same API as useState
        const valueToStore = value instanceof Function ? value(storedValue) : value;

        setStoredValue(valueToStore);

        if (typeof window === 'undefined') {
          return;
        }

        window.localStorage.setItem(key, JSON.stringify(valueToStore));
      } catch (error) {
        console.error(`Error writing to localStorage key "${key}":`, error);
      }
    },
    [key, storedValue],
  );

  // Remove from localStorage
  const removeValue = useCallback(() => {
    try {
      if (typeof window === 'undefined') {
        return;
      }

      window.localStorage.removeItem(key);
      setStoredValue(initialValue);
    } catch (error) {
      console.error(`Error removing from localStorage key "${key}":`, error);
    }
  }, [key, initialValue]);

  return [storedValue, setValue, removeValue] as const;
}

/**
 * API client wrapper for making HTTP requests
 */

import { API_BASE_URL, API_ENDPOINTS, RESPONSE_CODES } from '@/constants';
import type { ApiResponse, ApiError } from '@/types';

export interface RequestConfig {
  headers?: Record<string, string>;
  body?: any;
  params?: Record<string, any>;
  timeout?: number;
}

export class ApiClient {
  private baseUrl: string;
  private defaultHeaders: Record<string, string>;
  private timeout: number;

  constructor(baseUrl: string = API_BASE_URL, timeout: number = 30000) {
    this.baseUrl = baseUrl;
    this.timeout = timeout;
    this.defaultHeaders = {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
    };
  }

  private buildUrl(endpoint: string, params?: Record<string, any>): string {
    const url = new URL(endpoint, this.baseUrl);

    if (params) {
      Object.entries(params).forEach(([key, value]) => {
        if (value !== null && value !== undefined) {
          url.searchParams.append(key, String(value));
        }
      });
    }

    return url.toString();
  }

  private async request<T = any>(
    method: string,
    endpoint: string,
    config: RequestConfig = {},
  ): Promise<ApiResponse<T>> {
    const { headers = {}, body, params, timeout = this.timeout } = config;

    const url = this.buildUrl(endpoint, params);

    const requestHeaders: Record<string, string> = {
      ...this.defaultHeaders,
      ...headers,
    };

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    try {
      const response = await fetch(url, {
        method,
        headers: requestHeaders,
        body: body ? JSON.stringify(body) : undefined,
        credentials: 'include',
        signal: controller.signal,
      });

      const data: ApiResponse<T> = await response.json();

      if (!response.ok) {
        console.error(`API Error [${response.status}]:`, data);
      }

      return data;
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') {
        return {
          success: false,
          statusCode: RESPONSE_CODES.INTERNAL_SERVER_ERROR,
          error: 'Request timeout',
        };
      }

      console.error('API Request Error:', error);

      return {
        success: false,
        statusCode: RESPONSE_CODES.INTERNAL_SERVER_ERROR,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    } finally {
      clearTimeout(timeoutId);
    }
  }

  async get<T = any>(endpoint: string, config: RequestConfig = {}): Promise<ApiResponse<T>> {
    return this.request<T>('GET', endpoint, config);
  }

  async post<T = any>(
    endpoint: string,
    body?: any,
    config: RequestConfig = {},
  ): Promise<ApiResponse<T>> {
    return this.request<T>('POST', endpoint, { ...config, body });
  }

  async patch<T = any>(
    endpoint: string,
    body?: any,
    config: RequestConfig = {},
  ): Promise<ApiResponse<T>> {
    return this.request<T>('PATCH', endpoint, { ...config, body });
  }

  async put<T = any>(
    endpoint: string,
    body?: any,
    config: RequestConfig = {},
  ): Promise<ApiResponse<T>> {
    return this.request<T>('PUT', endpoint, { ...config, body });
  }

  async delete<T = any>(endpoint: string, config: RequestConfig = {}): Promise<ApiResponse<T>> {
    return this.request<T>('DELETE', endpoint, config);
  }
}

// Export singleton instance
export const apiClient = new ApiClient();
